fill(function(T)
  T["Henry wins the horse race (finishes first) and collects his winnings from Divis, then returns the horse to Zdena. The best possible result for both Henry and Zdena."] = "Heinrich gewinnt das Pferderennen (kommt als Erster ins Ziel), holt sich seinen Gewinn bei Herrn Diwisch ab und bringt das Pferd dann Zora zurück. Das bestmögliche Ergebnis für Heinrich wie für Zora."
  T["Henry finishes the race but not in first place, receives a partial payout from Divis, and returns the horse to Zdena. A middling result — some reward but not the full prize."] = "Heinrich beendet das Rennen, aber nicht als Erster, erhält von Herrn Diwisch einen Teil des Gewinns und bringt das Pferd Zora zurück. Ein mittelmäßiges Ergebnis – etwas Lohn, aber nicht der volle Preis."
  T["Henry finishes the race in last place or fails to complete it, receives nothing or a consolation from Divis, and returns the horse to Zdena. The worst race outcome short of a quest failure."] = "Heinrich wird im Rennen Letzter oder kommt gar nicht ins Ziel, erhält von Herrn Diwisch nichts oder einen Trostpreis und bringt das Pferd Zora zurück. Der schlechteste Ausgang des Rennens, ohne dass die Quest scheitert."
  T["Zdena dies before TalkWithZdenaAfterRace is completed, causing the quest to be cancelled immediately via the DeadUnconsciousGate watchdog. The quest ends without resolution."] = "Zora stirbt, bevor TalkWithZdenaAfterRace abgeschlossen ist, und die Überwachung DeadUnconsciousGate bricht die Quest sofort ab. Die Quest endet ohne Auflösung."
  T["The quest horse dies during the GoWithHorseToTalmberk or WinRace phase, triggering an immediate CancelQuest via the DeadUnconsciousGate watchdog on quest_horse. The quest ends without the race being run."] = "Das Questpferd stirbt in der Phase GoWithHorseToTalmberk oder WinRace, und die Überwachung DeadUnconsciousGate auf quest_horse löst sofort CancelQuest aus. Die Quest endet, ohne dass das Rennen stattfindet."
  T["The player fails to arrive at the starting area in time for the race. Divis cannot start the race, the global flag q_racingAndBetting_playerDidntArriveToRace is set, and the quest proceeds to TalkWithDivisAfterRace with a result code of 4 (did not arrive), leading to the lost-result dialogue path."] = "Der Spieler ist nicht rechtzeitig am Start. Herr Diwisch kann das Rennen nicht beginnen, die globale Variable q_racingAndBetting_playerDidntArriveToRace wird gesetzt, und die Quest geht mit dem Ergebniscode 4 (nicht erschienen) zu TalkWithDivisAfterRace über, wo der Dialog für ein verlorenes Rennen folgt."
  T["Henry finds the abbot's list, reads it, and logs all four monks (Cizek, Jodok, Antonin, Lukas), completing the quest. This is the single linear path through the quest."] = "Heinrich findet die Liste des Abtes, liest sie und erfasst alle vier Mönche (die Novizen Konstantin, Joachim, Antonius und Lukas), womit die Quest abgeschlossen ist. Das ist der einzige, lineare Weg durch die Quest."
  T["Henry finds Ester's location, frees her from the bandit hideout, and escorts her to safety. The quest completes normally with a reward after talking to Ester."] = "Heinrich findet heraus, wo Esther festgehalten wird, befreit sie aus dem Banditenversteck und bringt sie in Sicherheit. Nach dem Gespräch mit Esther wird die Quest regulär mit Belohnung abgeschlossen."
  T["Henry kills or incapacitates all bandits first, then frees Ester and escorts her to safety, optionally interrogating the last surviving bandit and sending him to prison."] = "Heinrich tötet oder überwältigt zuerst alle Banditen, befreit dann Esther und bringt sie in Sicherheit; wahlweise verhört er den letzten überlebenden Banditen und schickt ihn ins Gefängnis."
  T["Ester dies during the quest, causing it to be immediately cancelled with no reward."] = "Esther stirbt während der Quest, die daraufhin sofort ohne Belohnung abgebrochen wird."
  T["The parent quest (q_counterfeiters) ends before Henry rescues Ester, starting a timeout; if Henry then moves too far from the hideout without rescuing her, the quest is cancelled as failed."] = "Die übergeordnete Quest (q_counterfeiters) endet, bevor Heinrich Esther rettet, und eine Frist beginnt; entfernt sich Heinrich dann zu weit vom Versteck, ohne sie gerettet zu haben, wird die Quest als gescheitert abgebrochen."
  T["Florian (the quest giver) dies during the quest, causing it to be immediately cancelled."] = "Florian (der Auftraggeber) stirbt während der Quest, die daraufhin sofort abgebrochen wird."
  T["The player participates in the archery contest at Mrchojed and receives a reward based on their performance. The quest ends after the reward is collected."] = "Der Spieler nimmt am Bogenwettbewerb in Merhojed teil und erhält je nach Leistung eine Belohnung. Die Quest endet, sobald die Belohnung abgeholt ist."
  T["Henry enters the beginner archery contest and wins, receiving the prize money and XP reward. The shootmaster congratulates him."] = "Heinrich tritt im Bogenwettbewerb der Anfänger an und gewinnt; er erhält das Preisgeld und Erfahrungspunkte. Der Bogenmeister gratuliert ihm."
  T["Henry enters the advanced archery contest and wins, receiving the prize money and XP reward. The shootmaster congratulates him."] = "Heinrich tritt im Bogenwettbewerb der Fortgeschrittenen an und gewinnt; er erhält das Preisgeld und Erfahrungspunkte. Der Bogenmeister gratuliert ihm."
  T["Henry enters the expert archery contest and wins, receiving the prize money and XP reward. The shootmaster congratulates him."] = "Heinrich tritt im Bogenwettbewerb der Experten an und gewinnt; er erhält das Preisgeld und Erfahrungspunkte. Der Bogenmeister gratuliert ihm."
  T["Henry participates in the archery contest but loses, forfeiting his bet. The shootmaster delivers a commiserating monologue."] = "Heinrich nimmt am Bogenwettbewerb teil, verliert aber und büßt seinen Einsatz ein. Der Bogenmeister hält einen mitfühlenden Monolog."
  T["Henry participates in and finishes the archery contest in Rataje, receiving a reward based on his performance. The quest ends after the contest concludes and rewards are distributed."] = "Heinrich nimmt am Bogenwettbewerb in Rattay teil, bringt ihn zu Ende und erhält je nach Leistung eine Belohnung. Die Quest endet, wenn der Wettbewerb vorbei ist und die Belohnungen verteilt sind."
  T["Henry wins the beginner-tier archery contest and receives the corresponding XP reward and prize money."] = "Heinrich gewinnt den Bogenwettbewerb auf Anfängerstufe und erhält die entsprechenden Erfahrungspunkte und das Preisgeld."
  T["Henry wins the advanced-tier archery contest and receives the corresponding XP reward and prize money."] = "Heinrich gewinnt den Bogenwettbewerb auf Fortgeschrittenenstufe und erhält die entsprechenden Erfahrungspunkte und das Preisgeld."
  T["Henry wins the expert-tier archery contest and receives the corresponding XP reward and prize money."] = "Heinrich gewinnt den Bogenwettbewerb auf Expertenstufe und erhält die entsprechenden Erfahrungspunkte und das Preisgeld."
  T["Henry loses the archery contest at any difficulty tier, forfeiting his bet to the shootmaster."] = "Heinrich verliert den Bogenwettbewerb auf irgendeiner Stufe und büßt seinen Einsatz an den Bogenmeister ein."
  T["Henry enters the beginner archery contest and wins. He receives an XP reward appropriate to the beginner difficulty."] = "Heinrich tritt im Bogenwettbewerb der Anfänger an und gewinnt. Er erhält so viele Erfahrungspunkte, wie der Anfängerstufe entspricht."
  T["Henry enters the advanced archery contest and wins. He receives an XP reward appropriate to the advanced difficulty."] = "Heinrich tritt im Bogenwettbewerb der Fortgeschrittenen an und gewinnt. Er erhält so viele Erfahrungspunkte, wie der Fortgeschrittenenstufe entspricht."
  T["Henry enters the expert archery contest and wins. He receives an XP reward appropriate to the expert difficulty."] = "Heinrich tritt im Bogenwettbewerb der Experten an und gewinnt. Er erhält so viele Erfahrungspunkte, wie der Expertenstufe entspricht."
  T["Henry enters an archery contest at any difficulty and loses. He receives a consolation XP reward and forfeits his wager."] = "Heinrich tritt in einem Bogenwettbewerb beliebiger Stufe an und verliert. Er erhält ein paar Erfahrungspunkte als Trost und büßt seinen Einsatz ein."
  T["Henry gains Bohuta's trust by drinking with him, surviving the party brawl, ringing the bell, and witnessing the sheep scene at dawn. Bohuta reveals Kuba's secret, Henry investigates the black book and reports to Ledecko, completing the quest."] = "Heinrich gewinnt Pater Godwins Vertrauen: Er zecht mit ihm, übersteht die Prügelei auf dem Gelage, läutet die Glocke und erlebt im Morgengrauen die Szene mit dem Schaf. Pater Godwin verrät das Geheimnis des Hinkenden Heinz, Heinrich durchsucht die Schwarzen Chroniken und folgt der Spur nach Ledetschko, womit die Quest abgeschlossen ist."
  T["Henry accidentally reads the Ratay black book before Bohuta reveals the secret, learns about Hynek in Ledecko independently, and completes the quest without fully gaining Bohuta's trust through the drinking route."] = "Heinrich liest zufällig in den Schwarzen Chroniken von Rattay, bevor Pater Godwin das Geheimnis verrät, erfährt selbst von Stinker in Ledetschko und schließt die Quest ab, ohne Pater Godwins Vertrauen über das Zechgelage ganz gewonnen zu haben."
  T["Bohuta refuses to help Henry (due to failed drinking session, skipped mass, or canceled getDrunkWithBohuta), so Henry investigates the black book directly and reports to Ledecko to close the quest."] = "Pater Godwin weigert sich, Heinrich zu helfen (weil das Zechen schiefging, die Messe ausfiel oder getDrunkWithBohuta abgebrochen wurde), also durchsucht Heinrich die Schwarzen Chroniken selbst und folgt der Spur nach Ledetschko, um die Quest abzuschließen."
  T["After completing findOutMoreAboutKuba, the quest transitions into the revenge follow-up quest q_revenge_auschitz_ledetchko rather than ending immediately."] = "Nach findOutMoreAboutKuba endet die Quest nicht sofort, sondern geht in die Rache-Folgequest q_revenge_auschitz_ledetchko über."
  T["Henry finds a cure and delivers it to the ailing Bedrich in time, restoring his health and allowing Bedrich to assist with the black book investigation."] = "Heinrich findet ein Heilmittel und bringt es rechtzeitig zum kranken Schreiber; der wird wieder gesund und kann bei der Suche in den Schwarzen Chroniken helfen."
  T["Henry fails to deliver the cure to Bedrich before the timeout expires, leaving Bedrich unable to help with the investigation."] = "Heinrich bringt dem Schreiber das Heilmittel nicht vor Ablauf der Frist, sodass der Schreiber bei der Suche nicht helfen kann."
  T["Henry participates in and successfully conducts the mass with Bohuta, earning Bohuta's goodwill and progressing toward his trust."] = "Heinrich hält zusammen mit Pater Godwin erfolgreich die Messe, gewinnt so sein Wohlwollen und kommt seinem Vertrauen näher."
  T["Henry fails or skips the mass, angering Bohuta and forcing the bohutaWontHelp path where Henry must find the black book on his own."] = "Heinrich verpatzt die Messe oder bleibt ihr fern, verärgert damit Pater Godwin und landet auf dem Weg bohutaWontHelp, auf dem er die Schwarzen Chroniken selbst finden muss."
  T["Henry obtains the Avalon steel and brings it to the blacksmith, completing the errand. The quest ends after the steel is successfully delivered."] = "Heinrich beschafft den fremden Stahl und bringt ihn dem Schmied, womit der Auftrag erledigt ist. Die Quest endet, sobald der Stahl abgeliefert ist."
  T["Henry wakes in Rattay, speaks with Tereza across three dialog scenes, experiences the dream sequence, then meets Radzig Kobyla — completing the quest and transitioning into the main story. This is the only narrative ending; the quest is a linear prologue with no branching failure states."] = "Heinrich erwacht in Rattay, spricht in drei Dialogszenen mit Theresa, durchlebt die Traumsequenz und trifft dann Herrn Radzig Kobyla – damit ist die Quest abgeschlossen, und die Hauptgeschichte beginnt. Das ist das einzige erzählerische Ende; die Quest ist ein linearer Prolog ohne Verzweigungen, an denen sie scheitern könnte."
  T["Henry completes the full basic training, wins both the archery contest and the sword duel against Ptacek, then reports back to the Bailiff (Rychtar). He leaves Rattay's training ground having impressed Bernard."] = "Heinrich absolviert die gesamte Grundausbildung, gewinnt gegen Herrn Hans Capon sowohl den Bogenwettbewerb als auch den Schwertkampf und meldet sich dann beim Vogt zurück. Er verlässt den Übungsplatz von Rattay, nachdem er Hauptmann Bernard beeindruckt hat."
  T["Henry completes the full basic training but loses the archery contest against Ptacek, then wins the sword duel and reports back to the Bailiff. Training is finished regardless of the bow result."] = "Heinrich absolviert die gesamte Grundausbildung, verliert aber den Bogenwettbewerb gegen Herrn Hans Capon, gewinnt dann den Schwertkampf und meldet sich beim Vogt zurück. Die Ausbildung ist unabhängig vom Ergebnis mit dem Bogen beendet."
  T["Henry completes the full basic training, wins the archery contest but loses the sword duel against Ptacek, then reports back to the Bailiff. Training is finished regardless of the sword result."] = "Heinrich absolviert die gesamte Grundausbildung, gewinnt den Bogenwettbewerb, verliert aber den Schwertkampf gegen Herrn Hans Capon und meldet sich dann beim Vogt zurück. Die Ausbildung ist unabhängig vom Ergebnis mit dem Schwert beendet."
  T["Henry completes the full basic training but loses both the archery contest and the sword duel, then reports back to the Bailiff. Bernard dismisses him having shown he still has much to learn."] = "Heinrich absolviert die gesamte Grundausbildung, verliert aber sowohl den Bogenwettbewerb als auch den Schwertkampf und meldet sich dann beim Vogt zurück. Hauptmann Bernard entlässt ihn, denn er hat gezeigt, dass er noch viel zu lernen hat."
  T["Henry gathers all the required ingredients, brews the correct antidote, administers it to the cow, and waits for it to recover. The cow survives and the quest ends successfully."] = "Heinrich sammelt alle nötigen Zutaten, braut das richtige Gegengift, gibt es der Kuh und wartet, bis sie sich erholt. Die Kuh überlebt, und die Quest endet erfolgreich."
  T["Henry brews or uses the wrong antidote but gives it to the cow anyway, and the cow still recovers after waiting. The quest ends but with a less ideal remedy."] = "Heinrich braut oder verwendet das falsche Gegengift, gibt es der Kuh trotzdem, und die Kuh erholt sich nach einer Weile dennoch. Die Quest endet, aber mit einem weniger guten Heilmittel."
  T["Henry steals the monstrance (pyx) and hides it in a neighbour's chest, then reports the theft to the bailiff, framing an innocent farmer. The quest ends with the neighbour facing false accusation."] = "Heinrich stiehlt die Monstranz (Pyxis), versteckt sie in der Truhe eines Nachbarn und meldet dem Vogt dann den Diebstahl, womit er die Tat einem unschuldigen Bauern unterschiebt. Die Quest endet damit, dass der Nachbar zu Unrecht beschuldigt wird."
  T["The cow dies before Henry can administer the antidote. The quest is cancelled by the engine when CowDeath is completed."] = "Die Kuh stirbt, bevor Heinrich ihr das Gegengift geben kann. Die Engine bricht die Quest ab, sobald CowDeath abgeschlossen ist."
  T["Henry steals the brocade and brings it directly to Miller Simon (Woyzeck path), completing the job without involving the assistant or going to Neuhoff. The quest ends with the brocade delivered to the miller."] = "Heinrich stiehlt den Brokatstoff und bringt ihn direkt zu Müller Simon (Woyzeck-Weg); er erledigt den Auftrag, ohne den Gehilfen einzubeziehen oder nach Neuhof zu gehen. Die Quest endet damit, dass der Brokat beim Müller ist."
  T["Henry follows the assistant Michael to the fence at Neuhoff and delivers the brocade there, completing the alternative handoff path. The quest ends once the brocade reaches Neuhoff."] = "Heinrich folgt dem Gehilfen zum Hehler in Neuhof und liefert den Brokatstoff dort ab, über den alternativen Übergabeweg. Die Quest endet, sobald der Brokat in Neuhof ist."
  T["The assistant Michael reaches the map boundary with the brocade still in his possession and escapes, causing the quest to be cancelled via QuestSystem.CancelQuest. Henry loses the brocade and the job fails."] = "Der Gehilfe erreicht mit dem Brokatstoff den Kartenrand und entkommt, woraufhin die Quest über QuestSystem.CancelQuest abgebrochen wird. Heinrich verliert den Brokat, und der Auftrag scheitert."
  T["Henry resolves the bullying of Novice Lukas through peaceful means — either by reporting the circators to the prior, successfully threatening them, or finding a diplomatic solution — then reports back to complete the quest."] = "Heinrich beendet die Schikanen gegen Novize Lukas auf friedlichem Weg – er meldet die Circatoren beim Prior, schüchtert sie erfolgreich ein oder findet eine diplomatische Lösung – und meldet sich dann zurück, um die Quest abzuschließen."
  T["Henry reports the circators' misconduct to the prior or abbot, which counts as a successful resolution and feeds into the main completion path."] = "Heinrich meldet das Fehlverhalten der Circatoren beim Prior oder beim Abt; das gilt als erfolgreiche Lösung und führt zum regulären Abschluss."
  T["Henry intimidates the circators into backing off, resolving the bullying through threats rather than official channels."] = "Heinrich schüchtert die Circatoren ein, bis sie ablassen, und beendet die Schikanen mit Drohungen statt auf dem Dienstweg."
  T["Novice Lukas dies during the quest, causing the quest to be cancelled as a failure with no resolution."] = "Novize Lukas stirbt während der Quest, die daraufhin als gescheitert und ohne Lösung abgebrochen wird."
  T["Both circators are killed by Henry, which immediately cancels the quest as a failure rather than resolving it through legitimate means."] = "Heinrich tötet beide Circatoren, was die Quest sofort als gescheitert abbricht, statt sie auf rechtmäßigem Weg zu lösen."
  T["Henry is sent to solitary confinement, interrupting the quest and triggering a handoff to the monastery solitary objective in q_sazavaMonastery."] = "Heinrich kommt in Einzelhaft; das unterbricht die Quest und übergibt an die Klosteraufgabe zur Einzelhaft in q_sazavaMonastery."
  T["Henry obtains the cure, heals the captive bandit, interrogates him once healthy, and reports back to Racek. The captive survives and provides information about the counterfeiters."] = "Heinrich beschafft das Heilmittel, heilt den gefangenen Banditen, verhört ihn, sobald er gesund ist, und erstattet Herrn Radzig Bericht. Der Gefangene überlebt und gibt Auskunft über die Falschmünzer."
  T["Henry heals the captive and escorts him to the jail in Rataje rather than interrogating him on the spot, then reports to Racek. The captive is imprisoned alive."] = "Heinrich heilt den Gefangenen und bringt ihn ins Gefängnis von Rattay, statt ihn an Ort und Stelle zu verhören, und erstattet dann Herrn Radzig Bericht. Der Gefangene wird lebend eingesperrt."
  T["Henry kills the captive bandit himself, loots the letter from the body, and reports to Racek. The captive dies and the information is obtained through murder."] = "Heinrich tötet den gefangenen Banditen selbst, nimmt den Brief von der Leiche und erstattet Herrn Radzig Bericht. Der Gefangene stirbt, und die Information wird durch Mord beschafft."
  T["Henry administers a bad cure (poison or wrong substance) to the captive, who dies from it. Henry then inspects the body and reports to Racek."] = "Heinrich verabreicht dem Gefangenen ein falsches Heilmittel (Gift oder einen falschen Stoff), an dem er stirbt. Heinrich untersucht dann die Leiche und erstattet Herrn Radzig Bericht."
  T["The villagers lynch the captive before Henry can save him. Henry is teleported away during the lynch mob scene and must report to Racek with the captive dead."] = "Die Dorfbewohner lynchen den Gefangenen, bevor Heinrich ihn retten kann. Heinrich wird während der Szene mit dem Lynchmob fortteleportiert und muss Herrn Radzig melden, dass der Gefangene tot ist."
  T["Henry steals the incriminating letter from the captive without killing or healing him, then reports to Racek with the document as evidence."] = "Heinrich stiehlt dem Gefangenen den belastenden Brief, ohne ihn zu töten oder zu heilen, und erstattet dann Herrn Radzig mit dem Dokument als Beweis Bericht."
  T["Henry fails to obtain a cure in time and the captive dies from the plague. The quest proceeds to a failed state with the captive dead from illness."] = "Heinrich beschafft nicht rechtzeitig ein Heilmittel, und der Gefangene stirbt an der Pest. Die Quest geht in einen gescheiterten Zustand über, der Gefangene ist an der Krankheit gestorben."
  T["The quest is canceled or fails entirely, triggering the questFailed objective and bypassing the normal ending cutscene."] = "Die Quest wird abgebrochen oder scheitert ganz; das löst die Aufgabe questFailed aus und überspringt die reguläre Abschluss-Zwischensequenz."
  T["Henry helps Drahomira by gathering fumigation items, performing the fumigation ritual, consulting the apothecary, finding Lada's grave, and completing the incantation at the graveside with the apothecary. The ghost of Alois is laid to rest and a cross is erected at the quarry, concluding the quest with a reward from Kunhuta."] = "Heinrich hilft Drahomira: Er sammelt Dinge zum Ausräuchern, vollzieht das Räucherritual, fragt den Apotheker um Rat, findet Laras Grab und spricht mit dem Apotheker am Grab die Beschwörung zu Ende. Der Geist von Alois findet Ruhe, am Steinbruch wird ein Kreuz errichtet, und die Quest endet mit einer Belohnung vom Kräuterweib Kunhuta."
  T["The quest is forcibly cancelled by the engine when Drahomira, Kunhuta, or Konyas (the apothecary) is killed at any point during the quest. No resolution is reached and the haunting remains unsettled."] = "Die Engine bricht die Quest zwangsweise ab, sobald Drahomira, das Kräuterweib Kunhuta oder der Apotheker irgendwann während der Quest getötet wird. Es gibt keine Lösung, und der Spuk bleibt ungeklärt."
  T["Henry gathers all three ritual items (tooth, branch, talisman), delivers them to the charlatan, obtains Loukota's shroud, and gives it to the charlatan. The charlatan is then publicly expelled from town by the brawlers in a cutscene."] = "Heinrich sammelt alle drei Ritualgegenstände (Zahn, Zweig, Talisman), bringt sie dem Scharlatan, beschafft Lokotas Leichentuch und gibt es dem Scharlatan. In einer Zwischensequenz jagen die Raufbolde den Scharlatan dann öffentlich aus der Stadt."
  T["The charlatan dies during the quest, causing it to be cancelled outright with no resolution for Loukota."] = "Der Scharlatan stirbt während der Quest, die daraufhin ohne Lösung für Lokota abgebrochen wird."
  T["Henry kills one of Loukota's brothers (Petr or Marek) and the charlatan reports the crime to the authorities, causing the quest to be cancelled."] = "Heinrich tötet einen von Lokotas Brüdern (Peter oder Mark), und der Scharlatan meldet das Verbrechen der Obrigkeit, woraufhin die Quest abgebrochen wird."
  T["Henry investigates the construction site murder, identifies Zmola as the killer, and has him arrested and brought to justice. The quest concludes with a report back to the quest giver (Divis, the quarry master, or Schaefer)."] = "Heinrich untersucht den Mord auf der Baustelle, überführt Zmola als Täter und sorgt dafür, dass er verhaftet und vor Gericht gestellt wird. Die Quest endet mit dem Bericht an den Auftraggeber (Herrn Diwisch, den Steinbruchmeister oder den Klostermeier)."
  T["Zmola flees the scene and escapes before Henry can apprehend him. Henry still reports back to the quest giver, but the killer is never brought to justice."] = "Zmola flieht vom Tatort und entkommt, bevor Heinrich ihn fassen kann. Heinrich erstattet dem Auftraggeber trotzdem Bericht, doch der Mörder wird nie zur Rechenschaft gezogen."
  T["Henry kills Zmola during the confrontation rather than arresting him. The quest can still conclude by reporting back to the quest giver, though justice is delivered by the sword rather than the law."] = "Heinrich tötet Zmola bei der Konfrontation, statt ihn zu verhaften. Die Quest kann trotzdem mit dem Bericht an den Auftraggeber enden, doch die Gerechtigkeit übt hier das Schwert, nicht das Gesetz."
  T["Zmola is killed before Henry has gathered enough evidence or reached the confrontation stage, making it impossible to properly resolve the murder investigation. The quest is cancelled."] = "Zmola wird getötet, bevor Heinrich genug Beweise gesammelt oder die Konfrontation erreicht hat, sodass sich der Mordfall nicht mehr richtig aufklären lässt. Die Quest wird abgebrochen."
  T["A critical NPC (Lesek before the skull investigation is complete, the doorman before speaking to the caretaker, or the knacker before skull authenticity is verified) is killed prematurely, blocking quest progression and causing the quest to be cancelled."] = "Ein wichtiger NPC (Leschek, bevor die Untersuchung des Schädels abgeschlossen ist, der Pförtner, bevor Heinrich mit dem Klostermeier gesprochen hat, oder der Schinder, bevor die Echtheit des Schädels geprüft ist) wird zu früh getötet; die Quest kommt nicht weiter und wird abgebrochen."
  T["Schaefer (the caretaker) is killed before Henry has a return-to-quest-giver objective active, leaving no one to report to and causing the quest to be cancelled."] = "Der Klostermeier wird getötet, bevor Heinrich eine Aufgabe zur Rückkehr zum Auftraggeber hat; niemand bleibt, dem er berichten könnte, und die Quest wird abgebrochen."
  T["Henry recovers the charcoal-burners' stolen loot and returns it to innkeeper Ondrej. The quest ends with Ondrej receiving the goods."] = "Heinrich holt die gestohlene Beute der Köhler zurück und gibt sie dem Wirt Andreas. Die Quest endet damit, dass Andreas die Waren erhält."
  T["Henry extorts or negotiates money from the colliers and returns the cash to Ondrej instead of the physical loot."] = "Heinrich presst den Köhlern Geld ab oder handelt es ihnen ab und bringt Andreas das Geld statt der Beute selbst."
  T["Henry recovers the stolen loot and returns it directly to Adam, the original victim, rather than to Ondrej."] = "Heinrich holt die gestohlene Beute zurück und gibt sie direkt Adam, dem eigentlichen Opfer, statt Andreas."
  T["Henry recovers the extorted money and returns it directly to Adam, giving him back the value of what was stolen."] = "Heinrich holt das erpresste Geld zurück und gibt es direkt Adam, der so den Wert des Gestohlenen zurückerhält."
  T["Henry recovers Adam's stolen necklace and returns it to him, completing the quest with the most personal of the stolen items restored."] = "Heinrich holt Adams gestohlene Halskette zurück und gibt sie ihm wieder; die Quest endet damit, dass das persönlichste der gestohlenen Stücke wieder bei ihm ist."
  T["Henry gives up on the quest after all the colliers are killed, leaving the matter unresolved. The quest is cancelled."] = "Heinrich gibt die Quest auf, nachdem alle Köhler getötet sind, und lässt die Sache ungeklärt. Die Quest wird abgebrochen."
  T["Adam is killed before Henry can complete the quest, causing it to be cancelled with the stolen goods never recovered."] = "Adam wird getötet, bevor Heinrich die Quest abschließen kann; sie wird abgebrochen, und das Gestohlene taucht nie wieder auf."
  T["Ondrej is killed during the quest, removing the quest giver and causing the quest to be cancelled."] = "Andreas wird während der Quest getötet; damit fällt der Auftraggeber weg, und die Quest wird abgebrochen."
  T["Henry and the Bohemian forces successfully storm Talmberg, breach the gate or scale the walls, fight through the courtyard, and chase down the fleeing Toth. The quest concludes with a cutscene showing Radzig and the credits sequence rolling into the dream-of-father epilogue."] = "Heinrich und die böhmischen Truppen stürmen Talmberg erfolgreich, durchbrechen das Tor oder erklimmen die Mauern, kämpfen sich durch den Burghof und jagen den fliehenden Herrn Istvan Toth. Die Quest endet mit einer Zwischensequenz mit Herrn Radzig, und der Abspann geht in den Epilog mit dem Traum vom Vater über."
  T["During the chase sequence after the castle falls, Henry rides outside the permitted boundary area instead of following Toth, triggering an immediate game-over screen with the reason ConquestFollowCapon or ConquestFled."] = "Während der Verfolgung nach dem Fall der Burg reitet Heinrich aus dem erlaubten Gebiet hinaus, statt Herrn Istvan Toth zu folgen; das löst sofort einen Game-Over-Bildschirm mit dem Grund ConquestFollowCapon oder ConquestFled aus."
  T["Henry and the Talmberg forces storm Vranik, breach both gates, clear the camp, and defeat the Cumans. The quest ends with the inner camp seized and a post-battle cutscene."] = "Heinrich und die Talmberger Truppen stürmen Wranik, durchbrechen beide Tore, räumen das Lager und besiegen die Kumanen. Die Quest endet mit dem eingenommenen inneren Lager und einer Zwischensequenz nach der Schlacht."
  T["Henry leaves the battle area during the assault, triggering an immediate game-over with the reason Q_IR_FledBattle."] = "Heinrich verlässt während des Sturms das Kampfgebiet; das löst sofort ein Game Over mit dem Grund Q_IR_FledBattle aus."
  T["The getReinforcements objective is canceled (e.g. Divis is killed or the condition fails), triggering a game-over with reason qco_reinforcements before the battle even begins."] = "Die Aufgabe getReinforcements wird abgebrochen (etwa weil Herr Diwisch getötet wird oder die Bedingung scheitert); das löst noch vor Beginn der Schlacht ein Game Over mit dem Grund qco_reinforcements aus."
  T["Henry and the allied forces complete all phases of the counter-offensive battle, breaching the gates and seizing both the outer and inner camps. This is the sole narrative conclusion of this scripted battle sequence."] = "Heinrich und die verbündeten Truppen bringen alle Phasen der Gegenoffensive hinter sich, durchbrechen die Tore und nehmen das äußere wie das innere Lager ein. Das ist der einzige erzählerische Abschluss dieser geskripteten Schlacht."
  T["Henry captures Jezek, delivers information to Racek, and brings the counterfeiting operation to justice. The main story path concludes with the workshop shut down and the criminals handed over to the authorities."] = "Heinrich nimmt Herrn Jeschek gefangen, überbringt Herrn Radzig die Informationen und bringt die Falschmünzer vor Gericht. Der Hauptstrang endet damit, dass die Werkstatt geschlossen und die Verbrecher der Obrigkeit übergeben sind."
  T["Henry kills Ulrich during or after the initial chase, loots the documents from his body, and proceeds to deliver them to Fejfar without Ulrich's cooperation. Ulrich dies before the investigation is properly concluded."] = "Heinrich tötet Ulrich während oder nach der ersten Verfolgung, nimmt die Dokumente von seiner Leiche und bringt sie ohne Ulrichs Mitwirkung zu Tobias Feyfar. Ulrich stirbt, bevor die Ermittlung richtig abgeschlossen ist."
  T["Henry kills Rapota during the confrontation at the mill or camp rather than capturing him. The operation is still dismantled but Rapota does not face formal justice."] = "Heinrich tötet Rapota bei der Konfrontation an der Mühle oder im Lager, statt ihn gefangen zu nehmen. Die Bande wird trotzdem zerschlagen, doch Rapota kommt nicht vor Gericht."
  T["Henry walks away from Rapota during the execution sequence, allowing him to escape. The counterfeiting ringleader goes free."] = "Heinrich wendet sich während der Hinrichtung von Rapota ab und lässt ihn entkommen. Der Kopf der Falschmünzer kommt frei."
  T["Henry reconciles with Ulrich, brings him to the workshop, and Ulrich spares Jezek during the confrontation. Jezek is captured peacefully and handed over."] = "Heinrich versöhnt sich mit Ulrich und bringt ihn zur Werkstatt, wo Ulrich Herrn Jeschek bei der Konfrontation verschont. Herr Jeschek wird friedlich gefangen genommen und übergeben."
  T["Henry brings Ulrich to the workshop but Ulrich turns on Henry over the fate of Jezek, forcing a fight. The alliance breaks down violently at the final confrontation."] = "Heinrich bringt Ulrich zur Werkstatt, doch Ulrich wendet sich wegen Herrn Jescheks Schicksal gegen Heinrich, und es kommt zum Kampf. Das Bündnis zerbricht bei der letzten Konfrontation gewaltsam."
  T["Henry finds the Beran family treasure and returns it (along with the goblet) to Mrs. Beran, the rightful owner. The debt is resolved in her favor."] = "Heinrich findet den Schatz der Familie Beran und gibt ihn (samt Becher) Berans Frau zurück, der rechtmäßigen Besitzerin. Die Schuld wird zu ihren Gunsten beglichen."
  T["Henry finds the treasure and returns it to Mr. Beran rather than his wife, resolving the debt but not necessarily in the most just way."] = "Heinrich findet den Schatz und gibt ihn Beran statt seiner Frau zurück; die Schuld ist beglichen, aber nicht unbedingt auf die gerechteste Weise."
  T["Henry recovers the debt money from Kunes and returns it to Mr. Beran after persuading him, without recovering the goblet."] = "Heinrich holt das Schuldgeld von Kunesch zurück und gibt es Beran, nachdem er ihn überzeugt hat, ohne den Becher wiederzubeschaffen."
  T["Henry recovers the debt money from Kunes and returns it to Mr. Beran without persuading him to a better outcome."] = "Heinrich holt das Schuldgeld von Kunesch zurück und gibt es Beran, ohne ihn zu einem besseren Ausgang zu bewegen."
  T["Henry recovers the goblet and returns it to Mrs. Beran, helping her reclaim what was taken from her."] = "Heinrich holt den Becher zurück und gibt ihn Berans Frau, die so zurückbekommt, was ihr genommen wurde."
  T["Henry returns the recovered treasure in a general resolution path, closing out the quest."] = "Heinrich gibt den gefundenen Schatz über einen allgemeinen Lösungsweg zurück und schließt die Quest damit ab."
  T["Henry acted dishonorably during the quest, extorting or betraying Beran. This decreases Henry's reputation with the refugees faction."] = "Heinrich hat sich während der Quest unehrenhaft verhalten und Beran erpresst oder verraten. Das senkt Heinrichs Ruf bei der Fraktion der Flüchtlinge."
  T["Kunes is killed during the quest, cutting off the possibility of a negotiated resolution to the debt."] = "Kunesch wird während der Quest getötet; damit ist keine ausgehandelte Lösung der Schuldfrage mehr möglich."
  T["Mr. Beran is killed during the quest, making a proper resolution of the debt impossible."] = "Beran wird während der Quest getötet, was eine ordentliche Begleichung der Schuld unmöglich macht."
  T["Mrs. Beran is killed during the quest, preventing her from receiving what is rightfully hers."] = "Berans Frau wird während der Quest getötet und kann nicht mehr bekommen, was ihr zusteht."
  T["Kunes defeats Henry in their confrontation, leaving the debt unresolved and Henry unconscious."] = "Kunesch besiegt Heinrich bei der Auseinandersetzung; die Schuld bleibt ungeklärt, und Heinrich liegt bewusstlos am Boden."
  T["Henry defeats Kunes in combat, forcing him to submit and admit the debt. The quest can then proceed to a resolution."] = "Heinrich besiegt Kunesch im Kampf, zwingt ihn zum Nachgeben und dazu, die Schuld zuzugeben. Danach kann die Quest zu einer Lösung kommen."
  T["Henry successfully defends the trebuchet until the bandit force is reduced, then participates in the post-battle negotiation cutscene and the final prisoner exchange, completing the quest. This is the intended full completion path."] = "Heinrich verteidigt den Tribok erfolgreich, bis die Banditen geschwächt sind, nimmt dann an der Verhandlung nach der Schlacht (Zwischensequenz) und am abschließenden Gefangenenaustausch teil und schließt die Quest ab. Das ist der vorgesehene vollständige Abschluss."
  T["Henry participates in the ritual, survives the attack by the two men (magor/magor2), and completes the quest. The afterAttack cutscene plays and the quest ends at the 'end' objective."] = "Heinrich nimmt am Ritual teil, übersteht den Angriff der beiden Männer (magor/magor2) und schließt die Quest ab. Die Zwischensequenz afterAttack läuft, und die Quest endet bei der Aufgabe „end“."
  T["Same as the normal completion but Henry also reports back to the herbalist Gertruda after the attack, triggering the afterAttackHerbalist objective before the quest ends."] = "Wie der reguläre Abschluss, doch Heinrich meldet sich nach dem Angriff außerdem beim Kräuterweib zurück; das löst vor dem Ende der Quest die Aufgabe afterAttackHerbalist aus."
  T["One of the three girls (Vera, Zlata, or Kuta) is killed before the attack phase, causing the quest to be immediately canceled."] = "Eines der drei Mädchen (Vera, Zlata oder Krista) wird vor der Angriffsphase getötet, und die Quest wird sofort abgebrochen."
  T["The herbalist Gertruda dies while the talkToHerbalist objective is active, causing the quest to be canceled."] = "Das Kräuterweib stirbt, während die Aufgabe talkToHerbalist aktiv ist, und die Quest wird abgebrochen."
  T["Henry flees the ritual area during the attack phase, triggering attackFlee and causing the girls to be killed and the quest to be canceled."] = "Heinrich flieht während der Angriffsphase vom Ritualplatz; das löst attackFlee aus, die Mädchen werden getötet, und die Quest wird abgebrochen."
  T["Henry enters the ritual area during the observeRitual phase but the interruptRitual objective is subsequently canceled (e.g. by leaving), causing the attack branch to cancel the quest."] = "Heinrich betritt in der Phase observeRitual den Ritualplatz, doch die Aufgabe interruptRitual wird danach abgebrochen (etwa weil er sich entfernt), sodass der Angriffszweig die Quest abbricht."
  T["Henry successfully helps the gang acquire Cuman disguises, reports back to Ondrej after the final cutscene, and the quest ends normally. This is the standard successful completion path."] = "Heinrich hilft der Bande erfolgreich, sich Kumanenverkleidungen zu beschaffen, meldet sich nach der letzten Zwischensequenz bei Andreas zurück, und die Quest endet regulär. Das ist der übliche erfolgreiche Abschluss."
  T["The quest fails because one of the key NPCs (Ondrej, Fricek, Matus, Milomir, Bran, Olena, or Vasek) is killed. The BT immediately starts failQuest when any of these death-tracker objectives complete, which then cancels the quest."] = "Die Quest scheitert, weil einer der wichtigen NPCs (Andreas, Fritz, Matthäus, Milomir, Brinus, Olena oder Willibald) getötet wird. Der Verhaltensbaum startet failQuest sofort, sobald eine dieser Aufgaben zur Todesüberwachung abgeschlossen ist, und das bricht die Quest dann ab."
  T["Henry successfully develops the village by restoring the church, achieving good income, and growing the population, then reports to Divis to complete the quest with a closing trialog cutscene."] = "Heinrich baut das Dorf erfolgreich auf: Er stellt die Kirche wieder her, sorgt für gute Einnahmen und lässt die Bevölkerung wachsen; dann meldet er sich bei Herrn Diwisch und schließt die Quest mit einem abschließenden Dreiergespräch als Zwischensequenz ab."
  T["The village's reputation with faction 96 drops to 0.15 or below while the daily income check is active, causing the quest to be automatically cancelled and the failure objective to be started."] = "Der Ruf des Dorfes bei Fraktion 96 sinkt auf 0.15 oder darunter, während die tägliche Einnahmenprüfung aktiv ist; die Quest wird automatisch abgebrochen und die Fehlschlag-Aufgabe gestartet."
  T["Henry sides with Krkovicka in the butcher dispute; Spejlik and the old butcher are banished from Pribyslavitz."] = "Heinrich stellt sich im Fleischerstreit auf die Seite von Fleischer Kochwurst; Fleischer Brisket und der alte Fleischer werden aus Pribyslawitz verbannt."
  T["Henry sides with Spejlik in the butcher dispute; Krkovicka and the old butcher are banished from Pribyslavitz."] = "Heinrich stellt sich im Fleischerstreit auf die Seite von Fleischer Brisket; Fleischer Kochwurst und der alte Fleischer werden aus Pribyslawitz verbannt."
  T["Henry recruits the new baker (Petr) and banishes the old baker from Pribyslavitz."] = "Heinrich wirbt den neuen Bäcker (Bäcker Silvester) an und verbannt den alten Bäcker aus Pribyslawitz."
  T["Henry banishes the new baker (Petr) from Pribyslavitz, keeping the old baker."] = "Heinrich verbannt den neuen Bäcker (Bäcker Silvester) aus Pribyslawitz und behält den alten Bäcker."
  T["Henry denounces the poachers to the authorities, applying the law strictly."] = "Heinrich zeigt die Wilderer bei der Obrigkeit an und wendet das Gesetz streng an."
  T["Henry confiscates the poachers' catch as punishment but lets them stay."] = "Heinrich beschlagnahmt zur Strafe die Beute der Wilderer, lässt sie aber bleiben."
  T["Henry lets the poachers keep their catch and overlooks the offence."] = "Heinrich lässt den Wilderern ihre Beute und sieht über das Vergehen hinweg."
  T["Henry forgives the two lazy friends (Fricek and Matus) outright and lets them stay without conditions."] = "Heinrich vergibt den beiden faulen Freunden (Fritz und Matthäus) ohne Weiteres und lässt sie bedingungslos bleiben."
  T["Henry gives Fricek and Matus one last chance; they are reassigned to productive work."] = "Heinrich gibt Fritz und Matthäus eine letzte Chance; sie werden zu nützlicher Arbeit eingeteilt."
  T["Henry banishes both Fricek and Matus from Pribyslavitz for their idleness."] = "Heinrich verbannt Fritz und Matthäus wegen ihrer Faulheit aus Pribyslawitz."
  T["Henry rules against Prachos and has the abusive husband punished."] = "Heinrich entscheidet gegen Alfred und lässt den gewalttätigen Ehemann bestrafen."
  T["Henry banishes Prachos's wife from Pribyslavitz."] = "Heinrich verbannt Alfreds Frau aus Pribyslawitz."
  T["Henry leaves the Prachos household situation unchanged."] = "Heinrich lässt die Lage in Alfreds Haushalt, wie sie ist."
  T["Henry awards ownership of the disputed cow to Ruch."] = "Heinrich spricht die umstrittene Kuh Ruch zu."
  T["Henry awards ownership of the disputed cow to Lumir."] = "Heinrich spricht die umstrittene Kuh Lumir zu."
  T["Henry confiscates the hoarded grain for the village."] = "Heinrich beschlagnahmt das gehortete Getreide für das Dorf."
  T["Henry orders fair payment for the grain rather than confiscating it."] = "Heinrich ordnet an, das Getreide angemessen zu bezahlen, statt es zu beschlagnahmen."
  T["Henry protects the accused witch and allows her to remain in Pribyslavitz."] = "Heinrich beschützt die als Hexe beschuldigte Frau und lässt sie in Pribyslawitz bleiben."
  T["Henry banishes the accused witch from Pribyslavitz."] = "Heinrich verbannt die als Hexe beschuldigte Frau aus Pribyslawitz."
  T["Henry allows the lumberjacks to continue exporting wood outside the village."] = "Heinrich erlaubt den Holzfällern, weiterhin Holz aus dem Dorf auszuführen."
  T["Henry banishes the lumberjacks from Pribyslavitz; Malina and Kunes are also removed as a consequence."] = "Heinrich verbannt die Holzfäller aus Pribyslawitz; Himbeer und Kunesch müssen deshalb ebenfalls gehen."
  T["Henry leaves the wood-export situation as it is, making no ruling."] = "Heinrich lässt die Holzausfuhr, wie sie ist, und trifft keine Entscheidung."
  T["Henry banishes Malina's wife from Pribyslavitz."] = "Heinrich verbannt Himbeers Frau aus Pribyslawitz."
  T["Henry arranges a financial payoff to settle the dispute with Malina's wife, who then leaves."] = "Heinrich legt den Streit mit Himbeers Frau durch eine Abfindung bei, woraufhin sie geht."
  T["Henry leaves Malina's domestic situation unchanged; Malina himself is subsequently removed from the lumberjack camp."] = "Heinrich lässt Himbeers häusliche Lage, wie sie ist; Himbeer selbst wird danach aus dem Holzfällerlager abgezogen."
  T["Henry sends no reinforcements to Pribyslavitz."] = "Heinrich schickt keine Verstärkung nach Pribyslawitz."
  T["Henry sends only varlets as reinforcements to Pribyslavitz."] = "Heinrich schickt nur Knechte als Verstärkung nach Pribyslawitz."
  T["Henry sends only lumberjacks as reinforcements to Pribyslavitz."] = "Heinrich schickt nur Holzfäller als Verstärkung nach Pribyslawitz."
  T["Henry sends both varlets and lumberjacks as reinforcements to Pribyslavitz."] = "Heinrich schickt Knechte und Holzfäller als Verstärkung nach Pribyslawitz."
  T["Henry rules that the latrine must be built far away from the village centre."] = "Heinrich entscheidet, dass die Latrine weit weg von der Dorfmitte gebaut werden muss."
  T["Henry reaches a compromise on the latrine placement acceptable to both parties."] = "Heinrich findet für den Standort der Latrine einen Kompromiss, mit dem beide Seiten leben können."
  T["Henry rules that people may relieve themselves anywhere, ignoring the hygiene complaint."] = "Heinrich entscheidet, dass die Leute ihre Notdurft überall verrichten dürfen, und übergeht die Beschwerde über die Hygiene."
  T["Henry orders the baker to produce large loaves of bread."] = "Heinrich weist den Bäcker an, große Brotlaibe zu backen."
  T["Henry orders the baker to produce black bread for the villagers."] = "Heinrich weist den Bäcker an, Schwarzbrot für die Dorfbewohner zu backen."
  T["Henry installs scales in the town hall to ensure fair bread weight; the newhomes_townhall_scales profile is enabled."] = "Heinrich lässt im Rathaus eine Waage aufstellen, damit das Brotgewicht stimmt; das Profil newhomes_townhall_scales wird aktiviert."
  T["Henry's ruling leaves the villagers hungry — the bread dispute is resolved against the people's interests."] = "Heinrichs Entscheidung lässt die Dorfbewohner hungern – der Brotstreit wird gegen die Interessen der Leute entschieden."
  T["Henry rescues Kolikator from the bandit camp, escorts him through Pribyslavitz, attends the trialog with Divis, and reports to the Rattay bailiff who rings the bell to welcome the new settlers."] = "Heinrich rettet Marius aus dem Banditenlager, geleitet ihn durch Pribyslawitz, nimmt am Dreiergespräch mit Herrn Diwisch teil und meldet sich beim Vogt von Rattay, der die Glocke läutet, um die neuen Siedler willkommen zu heißen."
  T["Kolikator is killed before the quest can be completed, causing the quest to be cancelled and all related activities to shut down."] = "Marius wird getötet, bevor die Quest abgeschlossen werden kann; die Quest wird abgebrochen, und alle zugehörigen Aktivitäten werden beendet."
  T["The Rattay bailiff is killed after the quest has started, making it impossible to complete the settlement ceremony and cancelling the quest."] = "Der Vogt von Rattay wird nach Beginn der Quest getötet; die Siedlungszeremonie kann nicht mehr stattfinden, und die Quest wird abgebrochen."
  T["Henry recruits settlers for the new village by talking to various candidates across the region. The quest runs as a persistent background tracker with no single terminal ending — each successful recruit is migrated to the new settlement and the quest remains active as long as the parent DLC questline is active."] = "Heinrich wirbt Siedler für das neue Dorf an, indem er mit verschiedenen Kandidaten in der ganzen Gegend spricht. Die Quest läuft dauerhaft im Hintergrund mit und hat kein einzelnes Ende – jeder erfolgreich Angeworbene zieht in die neue Siedlung, und die Quest bleibt aktiv, solange die übergeordnete DLC-Questreihe aktiv ist."
  T["The minigame objective is completed (either by failure or a version-migration patch), which triggers an immediate DeactivateQuest call and shuts down the entire recruitment quest prematurely."] = "Die Minispiel-Aufgabe wird abgeschlossen (durch einen Fehlschlag oder einen Migrations-Patch zwischen Spielversionen); das löst sofort einen DeactivateQuest-Aufruf aus und beendet die gesamte Anwerbungsquest vorzeitig."
  T["Matus dies before being recruited, completing the matusIsDead objective and causing the game to deactivate his recruitment modifier, permanently removing him as a candidate for the new settlement."] = "Matthäus stirbt, bevor er angeworben ist; die Aufgabe matusIsDead wird abgeschlossen, und das Spiel deaktiviert seinen Anwerbungs-Modifikator, womit er als Kandidat für die neue Siedlung dauerhaft wegfällt."
  T["Fritz dies before being recruited, completing the fritzIsDead objective and causing the game to deactivate his recruitment modifier, permanently removing him as a candidate for the new settlement."] = "Fritz stirbt, bevor er angeworben ist; die Aufgabe fritzIsDead wird abgeschlossen, und das Spiel deaktiviert seinen Anwerbungs-Modifikator, womit er als Kandidat für die neue Siedlung dauerhaft wegfällt."
  T["Henry successfully defends Johana through the trial process, gathering testimonies and supporting her case. The trial ends happily with Johana acquitted and free."] = "Heinrich verteidigt Johanka erfolgreich im Prozess, sammelt Zeugenaussagen und stützt ihre Sache. Der Prozess endet glücklich: Johanka wird freigesprochen und ist frei."
  T["Henry fails to start the trial in time; the overtime expires and the trial is skipped, leading to a bad outcome for Johana. Henry must then speak with Nikotyn to learn what happened."] = "Heinrich bringt den Prozess nicht rechtzeitig in Gang; die Frist läuft ab, der Prozess wird übersprungen, und für Johanka geht es schlecht aus. Heinrich muss dann mit Bruder Nicodemus sprechen, um zu erfahren, was geschehen ist."
  T["Johana dies during the quest, causing it to be cancelled. The journal records her death and the quest ends without resolution."] = "Johanka stirbt während der Quest, die daraufhin abgebrochen wird. Das Questlog vermerkt ihren Tod, und die Quest endet ohne Lösung."
  T["Henry commits a crime against Johana (murder, assault, theft, or shooting at her), causing the quest to be cancelled immediately."] = "Heinrich begeht ein Verbrechen an Johanka (Mord, Angriff, Diebstahl oder ein Schuss auf sie), und die Quest wird sofort abgebrochen."
  T["Henry speaks heresy during the quest, triggering an immediate game over screen."] = "Heinrich äußert während der Quest Ketzerei, was sofort einen Game-Over-Bildschirm auslöst."
  T["The inquisitor is killed during the jail/trial phase, triggering an immediate game over."] = "Der Inquisitor wird während der Kerker- oder Prozessphase getötet, was sofort ein Game Over auslöst."
  T["Henry successfully finds Adela, deals with Henslin (scares him off, defeats him, or kills him), convinces Adela to leave, escorts her safely to Sazava, and the quest ends with her safe. This is the primary successful resolution."] = "Heinrich findet Adela, kümmert sich um Henslin (verscheucht, besiegt oder tötet ihn), überredet Adela zu gehen und geleitet sie sicher nach Sasau; die Quest endet mit ihr in Sicherheit. Das ist die wichtigste erfolgreiche Lösung."
  T["Henry escorts Adela but Henslin's men ambush them on the road; Henry defeats the ambush party and then escorts Adela safely to Sazava."] = "Heinrich geleitet Adela, doch Henslins Männer überfallen die beiden unterwegs; Heinrich besiegt die Angreifer und bringt Adela dann sicher nach Sasau."
  T["Adela is killed during the quest, either by Henry or by Henslin's men, causing the quest to be cancelled and fail."] = "Adela wird während der Quest getötet, entweder von Heinrich oder von Henslins Männern, woraufhin die Quest abgebrochen wird und scheitert."
  T["Henry takes too long to act while Adela is with Henslin; the timeout expires, Adela is left beaten and bloodied, and the quest fails."] = "Heinrich lässt sich zu viel Zeit, während Adela bei Henslin ist; die Frist läuft ab, Adela bleibt verprügelt und blutend zurück, und die Quest scheitert."
  T["Henry convinces Adela to leave but then abandons her during the escort; the adelaGoesHomeTimer expires, Adela gives up and goes home alone, and the quest fails."] = "Heinrich überredet Adela zu gehen, lässt sie aber unterwegs im Stich; adelaGoesHomeTimer läuft ab, Adela gibt auf und geht allein nach Hause, und die Quest scheitert."
  T["Henry strikes Adela during the quest, which immediately triggers a quest failure and makes Adela hostile or unwilling to cooperate."] = "Heinrich schlägt Adela während der Quest, was die Quest sofort scheitern lässt und Adela feindselig oder unwillig macht."
end)
fill(function(T)
  T["Henry kills Henslin in front of Adela while she is conscious and present; she witnesses the murder, becomes horrified, and the quest fails."] = "Heinrich tötet Henslin vor Adelas Augen, während sie bei Bewusstsein und anwesend ist; sie wird Zeugin des Mordes, ist entsetzt, und die Quest scheitert."
  T["The parent quest q_dlc_revelation is cancelled externally, which propagates a cancellation into this quest and forces it to fail."] = "Die übergeordnete Quest q_dlc_revelation wird von außen abgebrochen; der Abbruch greift auf diese Quest über und lässt sie scheitern."
  T["Henry confronts Henslin but loses the fight; a cutscene plays showing Henry's defeat and the quest fails."] = "Heinrich stellt Henslin, verliert aber den Kampf; eine Zwischensequenz zeigt Heinrichs Niederlage, und die Quest scheitert."
  T["Henry wins all of Ambroz's money at dice across three rounds, then convinces him to give up gambling. Ambroz quits and the tailor's wife is relieved."] = "Heinrich gewinnt Schneider Ambros in drei Würfelrunden sein ganzes Geld ab und überredet ihn dann, mit dem Spielen aufzuhören. Ambros hört auf, und die Frau des Schneiders ist erleichtert."
  T["Henry gets Ambroz blackout drunk, steals his money while he is passed out, then convinces him he lost it all at dice. Ambroz gives up gambling, though through deception."] = "Heinrich macht Ambros sturzbetrunken, stiehlt ihm sein Geld, während er bewusstlos ist, und redet ihm dann ein, er habe alles beim Würfeln verloren. Ambros gibt das Spielen auf, wenn auch durch Täuschung."
  T["Henry fails to help Ambroz through one of several bad choices: annoying him, stealing from him openly, being nasty after winning, getting too drunk himself, or letting Ambroz leave for Kuttenberg uncontested. The quest is cancelled."] = "Heinrich scheitert an einer von mehreren schlechten Entscheidungen daran, Ambros zu helfen: Er verärgert ihn, bestiehlt ihn offen, ist nach einem Sieg gehässig, betrinkt sich selbst zu sehr oder lässt Ambros ungehindert nach Kuttenberg aufbrechen. Die Quest wird abgebrochen."
  T["Henry kills either Ambroz or the tailor's wife during the quest, triggering an immediate quest failure and leaving Johanna in shock."] = "Heinrich tötet während der Quest Ambros oder die Frau des Schneiders; das lässt die Quest sofort scheitern, und Johanka ist erschüttert."
  T["Henry completes the penitent pilgrimage by visiting the chapel shrines, praying at the Maria statue, donating to Bohuta, and fulfilling his promise. The quest ends with Henry having done full penance for his sins."] = "Heinrich vollendet die Büßerwallfahrt: Er besucht die Kapellenschreine, betet an der Marienstatue, spendet Pater Godwin und hält sein Versprechen. Die Quest endet damit, dass Heinrich für seine Sünden volle Buße getan hat."
  T["Henry completes the pilgrimage and also retrieves and returns Bohuta's stolen book before fulfilling his promise. This is the most thorough completion of the quest."] = "Heinrich vollendet die Wallfahrt und bringt außerdem Pater Godwins gestohlenes Buch zurück, bevor er sein Versprechen erfüllt. Das ist der gründlichste Abschluss der Quest."
  T["Henry completes the pilgrimage via the alternative distance-based path, interacting with the player book position marker rather than speaking directly with Bohuta, then completing the penitent pilgrimage."] = "Heinrich vollendet die Wallfahrt über den alternativen, entfernungsbasierten Weg, indem er mit der Positionsmarkierung des Spielerbuchs interagiert, statt direkt mit Pater Godwin zu sprechen, und schließt dann die Büßerwallfahrt ab."
  T["Henry investigates the murders, identifies the killer, deals with him (kills or hands over), reports to Johanka, and the quest ends successfully. Sir Radzig may order the execution of the killer after being told."] = "Heinrich untersucht die Morde, überführt den Mörder, rechnet mit ihm ab (tötet ihn oder liefert ihn aus), erstattet Johanka Bericht, und die Quest endet erfolgreich. Herr Radzig ordnet womöglich die Hinrichtung des Mörders an, sobald er davon erfährt."
  T["The parent quest (q_dlc_revelation) fails while Henry has already started reporting to Johanka, causing this quest to be cancelled and the log_finalFail entry to fire."] = "Die übergeordnete Quest (q_dlc_revelation) scheitert, während Heinrich bereits dabei ist, Johanka Bericht zu erstatten; diese Quest wird abgebrochen, und der Eintrag log_finalFail wird ausgelöst."
  T["The master quest fails (mqFailed objective completes), triggering cancelQuest and finalCleanup, which cancels all active objectives and ends the quest without resolution."] = "Die Hauptquest scheitert (die Aufgabe mqFailed wird abgeschlossen); das löst cancelQuest und finalCleanup aus, die alle aktiven Aufgaben abbrechen und die Quest ohne Lösung beenden."
  T["Henry retrieves the treasure, donates all of it to the Church (parson, bailiff, or infirmarium), and reports back to Pavel, who is pleased with the outcome."] = "Heinrich holt den Schatz zurück, spendet ihn vollständig der Kirche (dem Pfarrer, dem Vogt oder der Krankenstube) und meldet sich bei Pavel zurück, der mit dem Ergebnis zufrieden ist."
  T["Henry retrieves the treasure but keeps some or all of it for himself rather than donating it fully, leaving Pavel disappointed."] = "Heinrich holt den Schatz zurück, behält aber einen Teil oder alles für sich, statt alles zu spenden, und enttäuscht damit Pavel."
  T["Henry failed to retrieve the treasure before the Cumans left with it; he returns to Pavel empty-handed with only a partial remnant left in the stash."] = "Heinrich hat den Schatz nicht zurückgeholt, bevor die Kumanen damit verschwunden sind; er kehrt mit leeren Händen zu Pavel zurück, im Versteck ist nur noch ein kleiner Rest."
  T["Pavel dies during the quest, triggering an automatic quest failure and cancellation."] = "Pavel stirbt während der Quest, was automatisch zum Scheitern und Abbruch der Quest führt."
  T["Henry gives up on the quest entirely, causing it to fail without completing Pavel's mission."] = "Heinrich gibt die Quest ganz auf, sodass sie scheitert, ohne dass Pavels Vorhaben erfüllt wird."
  T["Johanka is fully acquitted and her reputation is restored. Henry gathered enough evidence and made the right arguments during the trial to achieve the best possible verdict, with Matej also cured."] = "Johanka wird voll freigesprochen und ihr Ruf wiederhergestellt. Heinrich hat genug Beweise gesammelt und im Prozess die richtigen Argumente vorgebracht, um das bestmögliche Urteil zu erreichen, und auch Matthias ist geheilt."
  T["Johanka is acquitted with a good verdict. Henry presented sufficient evidence and testimony during the trial to secure her release, though not the ideal outcome."] = "Johanka wird mit einem guten Urteil freigesprochen. Heinrich hat im Prozess genug Beweise und Zeugenaussagen vorgelegt, um ihre Freilassung zu erreichen, wenn auch nicht das ideale Ergebnis."
  T["Johanka is condemned by the inquisitor. Either Henry skipped the trial, failed to gather enough evidence, or the judgment score was too low, resulting in the worst outcome for Johanka."] = "Johanka wird vom Inquisitor verurteilt. Entweder hat Heinrich den Prozess versäumt, nicht genug Beweise gesammelt, oder die Urteilswertung war zu niedrig – das schlechteste Ergebnis für Johanka."
  T["Henry never attended the trial. The skipTrial objective fires, cleanup_badEnd runs automatically, and Johanka is condemned without Henry ever participating."] = "Heinrich ist nie zum Prozess erschienen. Die Aufgabe skipTrial wird ausgelöst, cleanup_badEnd läuft automatisch, und Johanka wird verurteilt, ohne dass Heinrich je teilgenommen hat."
  T["Henry takes the dog (Vorech) as a companion. The dog is reassigned to Henry as its new master and the tutorial overlay for the dog companion is triggered."] = "Heinrich nimmt den Hund (Köter) als Begleiter auf. Der Hund bekommt Heinrich als neuen Herrn, und die Tutorial-Einblendung zum Hundebegleiter erscheint."
  T["The player completes the E3 2017 combat demo by triggering the endQuest trigger, which fires the 'end' objective and transitions to the next quest (q_raubritter). This is the sole narrative endpoint of this linear demo quest."] = "Der Spieler schließt die Kampfdemo der E3 2017 ab, indem er den Auslöser endQuest betätigt; dieser feuert die Aufgabe „end“ und leitet zur nächsten Quest (q_raubritter) über. Das ist der einzige erzählerische Endpunkt dieser linearen Demo-Quest."
  T["Henry successfully gains entry to the Sázava monastery by obtaining the required document and/or purse, traveling to the monastery, and either placing his belongings in the chest or putting on a novice robe. This is the intended completion of the quest."] = "Heinrich verschafft sich erfolgreich Zutritt zum Kloster Sasau: Er besorgt das nötige Dokument und/oder die Geldbörse, reist zum Kloster und legt entweder seine Habseligkeiten in die Truhe oder zieht eine Novizenkutte an. Das ist der vorgesehene Abschluss der Quest."
  T["The quest is forcibly canceled because Antonin or one of the novices inside the monastery was killed. The engine calls CancelQuest directly when antoninOrNoviceIsDead is completed while the quest is active."] = "Die Quest wird zwangsweise abgebrochen, weil Novize Antonius oder einer der Novizen im Kloster getötet wurde. Die Engine ruft direkt CancelQuest auf, wenn antoninOrNoviceIsDead abgeschlossen wird, während die Quest aktiv ist."
  T["Henry follows Ptacek out of Rattay and rides with him to the ruined camp, triggering the final cutscene and ending the game. This is the primary intended ending of KCD1."] = "Heinrich folgt Herrn Hans Capon aus Rattay hinaus und reitet mit ihm zum zerstörten Lager; das löst die letzte Zwischensequenz aus und beendet das Spiel. Das ist das wichtigste vorgesehene Ende von KCD1."
  T["Henry fails to follow Ptacek out of Rattay in time, so a stand-in NPC appears in Rattay for Henry to speak to, after which the final cutscene still plays and the game ends. This is the fallback path for players who dawdle."] = "Heinrich folgt Herrn Hans Capon nicht rechtzeitig aus Rattay hinaus; deshalb erscheint in Rattay ein Ersatz-NPC, mit dem Heinrich spricht, danach läuft trotzdem die letzte Zwischensequenz, und das Spiel endet. Das ist der Ausweichweg für Spieler, die trödeln."
  T["If the q_loveLetter quest is active and unfinished when the final marker fires, the quest briefly redirects Henry via Capon before restoring the end-game marker and completing normally. The game still ends via the standard cutscene."] = "Ist die Quest q_loveLetter aktiv und unerledigt, wenn die letzte Markierung auslöst, lenkt die Quest Heinrich kurz über Capon um, stellt dann die Markierung für das Spielende wieder her und schließt regulär ab. Das Spiel endet trotzdem mit der üblichen Zwischensequenz."
  T["Henry successfully escapes Talmberk after Zikmund's army arrives, either by jumping off the rampart or bribing/persuading/disguising his way through the outer gate, then rides toward Skalitz. This is the intended completion of the quest."] = "Nach der Ankunft von Sigismunds Heer entkommt Heinrich erfolgreich aus Talmberg, indem er entweder vom Wehrgang springt oder sich durch Bestechung, Überredung oder Verkleidung durch das äußere Tor schleicht, und reitet dann Richtung Skalitz. Das ist der vorgesehene Abschluss der Quest."
  T["Henry defeats all three fighters in the Rataje fight club and is crowned the champion. He wins the full prize money from each fighter."] = "Heinrich besiegt im Kampfklub von Rattay alle drei Kämpfer und wird zum Champion gekürt. Er gewinnt von jedem Kämpfer das volle Preisgeld."
  T["Henry is defeated in one of the fights and loses the bout. The fight club ends in failure for Henry."] = "Heinrich wird in einem der Kämpfe besiegt und verliert den Kampf. Der Kampfklub endet für Heinrich mit einer Niederlage."
  T["Henry wins the fights but receives reduced prize money from one or more fighters, having already beaten them in a previous encounter."] = "Heinrich gewinnt die Kämpfe, erhält aber von einem oder mehreren Kämpfern weniger Preisgeld, weil er sie schon bei einer früheren Begegnung besiegt hat."
  T["Henry defeats all the fighters in the Skalice fight club, including the Cuman King, and collects his winnings. The quest ends with Henry victorious and paid."] = "Heinrich besiegt alle Kämpfer im Kampfklub von Skalitz, darunter den König der Kumanen, und kassiert seinen Gewinn. Die Quest endet mit Heinrich als siegreichem und bezahltem Kämpfer."
  T["A key NPC (the speaker, Cuman King, Ase, or Asa) dies before the fight club can proceed, causing the quest to be cancelled."] = "Ein wichtiger NPC (der Ansager, der König der Kumanen, Ase oder Asa) stirbt, bevor der Kampfklub weitergehen kann, und die Quest wird abgebrochen."
  T["Henry defeats all four fight club opponents, completing the full circuit of brawlers. The fight club activity is fully cleared and a skill book reward is granted."] = "Heinrich besiegt alle vier Gegner des Kampfklubs und schließt die ganze Runde der Schläger ab. Die Kampfklub-Aktivität ist vollständig erledigt, und es gibt ein Fertigkeitenbuch als Belohnung."
  T["Henry is knocked unconscious during a bout or leaves the fight area, losing the current fight. The quest remains open and Henry can attempt fights again."] = "Heinrich wird während eines Kampfes bewusstlos geschlagen oder verlässt den Kampfbereich und verliert den aktuellen Kampf. Die Quest bleibt offen, und Heinrich kann erneut kämpfen."
  T["Henry completes all tasks for Stephanie — wine, horse, and tiara with moldavite — then dresses in her shirt, completing the romantic quest successfully."] = "Heinrich erledigt alle Aufträge für Herrin Stefanie – Wein, Pferd und Diadem mit Moldavit – und zieht dann ihr Hemd an, womit die romantische Quest erfolgreich abgeschlossen ist."
  T["A key NPC (engraver, Stephanie, Konrad, the groom, or the horse) dies during the quest, causing it to be cancelled with no resolution."] = "Ein wichtiger NPC (der Graveur, Herrin Stefanie, Konrad, der Stallbursche oder das Pferd) stirbt während der Quest, die daraufhin ohne Lösung abgebrochen wird."
  T["Henry wins the archery contest with more than 15 hits, impressing Vatzek and earning the best result. He can play again in the future."] = "Heinrich gewinnt den Bogenwettbewerb mit mehr als 15 Treffern, beeindruckt Vatzek und erzielt das beste Ergebnis. Er kann später erneut antreten."
  T["Henry wins the archery contest with 15 or fewer hits, beating both NPC competitors. Vatzek acknowledges the win."] = "Heinrich gewinnt den Bogenwettbewerb mit 15 oder weniger Treffern und schlägt beide NPC-Konkurrenten. Vatzek erkennt den Sieg an."
  T["Henry finishes in second place in the archery contest, neither winning nor coming last."] = "Heinrich wird im Bogenwettbewerb Zweiter, gewinnt also weder, noch wird er Letzter."
  T["Henry finishes last in the archery contest, losing to both NPC competitors."] = "Heinrich wird im Bogenwettbewerb Letzter und unterliegt beiden NPC-Konkurrenten."
  T["Henry left the firing area during the contest, which counts as cheating and disqualifies him with a score of -1."] = "Heinrich hat während des Wettbewerbs den Schießstand verlassen; das gilt als Schummeln und disqualifiziert ihn mit einer Wertung von -1."
  T["Henry attacked one of the archery contestants during the minigame, triggering the assault path and ending the contest early."] = "Heinrich hat während des Minispiels einen der Teilnehmer am Bogenwettbewerb angegriffen; das löst den Angriffszweig aus und beendet den Wettbewerb vorzeitig."
  T["Vacek, the archery organiser, is killed, causing the quest to be cancelled outright."] = "Vatzek, der Ausrichter des Bogenwettbewerbs, wird getötet, und die Quest wird sofort abgebrochen."
  T["Henry finds the chest, collects the sword and armor from it, then visits the blacksmith to sharpen the sword, completing the combat tutorial sequence. This is the only narrative path the quest supports."] = "Heinrich findet die Truhe, nimmt Schwert und Rüstung heraus und geht dann zum Schmied, um das Schwert zu schärfen; damit ist das Kampftutorial abgeschlossen. Das ist der einzige erzählerische Weg, den die Quest kennt."
  T["Henry retrieves the treasure and returns it to the quest giver, completing the stealth training exercise. The giver delivers a closing dialogue and the quest ends."] = "Heinrich holt den Schatz und bringt ihn dem Auftraggeber zurück, womit die Schleichübung abgeschlossen ist. Der Auftraggeber spricht ein paar abschließende Worte, und die Quest endet."
  T["Henry betrays Matus and Fricek to Sir Borek, leading to their execution at the gallows while Ondrej goes free. Henry earns the Judas achievement for this outcome."] = "Heinrich verrät Matthäus und Fritz an Herrn Robard; die beiden werden am Galgen hingerichtet, Andreas kommt frei. Für diesen Ausgang erhält Heinrich die Errungenschaft „Judas“."
  T["Henry reports the assault to Borek instead of helping Matus steal the money, ultimately resulting in Ondrej being hanged while Matus and Fricek escape justice."] = "Heinrich meldet den Überfall Herrn Robard, statt Matthäus beim Stehlen des Geldes zu helfen; am Ende wird Andreas gehängt, während Matthäus und Fritz der Strafe entgehen."
  T["All three brothers — Ondrej, Matus, and Fricek — are hanged. Henry earns the Judas achievement for engineering the deaths of all involved parties."] = "Alle drei Brüder – Andreas, Matthäus und Fritz – werden gehängt. Heinrich erhält die Errungenschaft „Judas“, weil er den Tod aller Beteiligten herbeigeführt hat."
  T["Matus and/or Fricek die before Henry can snitch to Borek, causing the quest to be cancelled with no execution outcome."] = "Matthäus und/oder Fritz sterben, bevor Heinrich sie bei Herrn Robard verraten kann; die Quest wird ohne Hinrichtung abgebrochen."
  T["Ondrej dies before the hanging can take place and neither ondrejHang nor allHang has been started, causing the quest to be cancelled outright."] = "Andreas stirbt, bevor die Hinrichtung stattfinden kann, und weder ondrejHang noch allHang wurde gestartet; die Quest wird sofort abgebrochen."
  T["Soldiers are already at the quarry when Henry tries to steal the money bag, making the theft impossible and cancelling the quest via the patch5 failsafe path."] = "Als Heinrich den Geldbeutel stehlen will, sind schon Soldaten am Steinbruch; der Diebstahl ist unmöglich, und die Quest wird über den Ausweichweg patch5 abgebrochen."
  T["Henry recovers the necklace through any means and returns it to Ptacek, completing the quest. The love letter subplot may or may not be active."] = "Heinrich beschafft die Halskette auf beliebigem Weg und gibt sie Herrn Hans Capon zurück, womit die Quest abgeschlossen ist. Die Nebenhandlung mit dem Liebesbrief kann aktiv sein oder auch nicht."
  T["Henry wins the dice tournament, collects the necklace from the chest or winner, and returns it to Ptacek."] = "Heinrich gewinnt das Würfelturnier, nimmt die Halskette aus der Truhe oder vom Gewinner und gibt sie Herrn Hans Capon zurück."
  T["Plch wins the tournament; Henry tracks him down, gets the necklace from him, and returns it to Ptacek."] = "Pechuna gewinnt das Turnier; Heinrich spürt ihn auf, bekommt die Halskette von ihm und gibt sie Herrn Hans Capon zurück."
  T["Henry negotiates with the bandit chief after round 2, obtains the necklace directly from him, and returns it to Ptacek."] = "Heinrich verhandelt nach Runde 2 mit dem Banditenanführer, bekommt die Halskette direkt von ihm und gibt sie Herrn Hans Capon zurück."
  T["Henry steals the necklace from the chest or stash without winning the tournament or negotiating, then returns it to Ptacek."] = "Heinrich stiehlt die Halskette aus der Truhe oder dem Versteck, ohne das Turnier zu gewinnen oder zu verhandeln, und gibt sie dann Herrn Hans Capon zurück."
  T["Henry reveals Adam's identity to the bandit chief, leading to Adam's death; Henry may still recover the necklace but at the cost of Adam's life."] = "Heinrich verrät dem Banditenanführer, wer Herr Anselm ist, und Herr Anselm bezahlt das mit dem Leben; Heinrich kann die Halskette trotzdem zurückholen, aber um den Preis von Herrn Anselms Leben."
  T["After the murder investigation, Henry accuses someone and Adam kills the accused person; the quest can still conclude with returning the necklace."] = "Nach der Mordermittlung beschuldigt Heinrich jemanden, und Herr Anselm tötet den Beschuldigten; die Quest kann trotzdem mit der Rückgabe der Halskette enden."
  T["Henry finds Father Simon being held by bullies, rescues him through combat, persuasion, money, or intimidation, then reports back to the farmer. The quest ends with the farmer rewarded and Simon safe."] = "Heinrich findet Pater Simon in der Gewalt von Rüpeln, befreit ihn durch Kampf, Überredung, Geld oder Einschüchterung und meldet sich dann beim Bauern zurück. Die Quest endet damit, dass der Bauer belohnt wird und Simon in Sicherheit ist."
  T["Either Father Simon or the Skalice parson dies during the quest, causing the quest to be cancelled as both key clerics are lost."] = "Pater Simon oder der Pfarrer von Skalitz stirbt während der Quest, die daraufhin abgebrochen wird, weil einer der beiden wichtigen Geistlichen fehlt."
  T["The farmer who gave Henry the quest is killed, making it impossible to complete the quest and causing it to be cancelled."] = "Der Bauer, der Heinrich die Quest gegeben hat, wird getötet; die Quest kann nicht mehr abgeschlossen werden und wird abgebrochen."
  T["Henry kills both bullies instead of driving them off or using a non-lethal approach, then reports back to the farmer. The quest still completes but Henry took lethal action against the thugs."] = "Heinrich tötet beide Rüpel, statt sie zu vertreiben oder gewaltlos vorzugehen, und meldet sich dann beim Bauern zurück. Die Quest wird trotzdem abgeschlossen, aber Heinrich hat die Schläger umgebracht."
  T["Henry defeats Jan Zajic in a duel, arrests him, and delivers him to Mikulas. The poacher ring is brought to justice through lawful means."] = "Heinrich besiegt Hanekin Hase im Duell, verhaftet ihn und übergibt ihn Wildhüter Nickolas. Die Wildererbande wird auf rechtmäßigem Weg zur Rechenschaft gezogen."
  T["Henry kills Jan Zajic during the duel at the glade. He recovers Zajic's ring and brings it to Mikulas to close the case."] = "Heinrich tötet Hanekin Hase beim Duell auf der Lichtung. Er nimmt den Ring von Hanekin Hase an sich und bringt ihn Wildhüter Nickolas, um den Fall abzuschließen."
  T["Jan Zajic successfully flees during the pursuit and escapes justice. The quest is cancelled with the poacher unpunished."] = "Hanekin Hase entkommt bei der Verfolgung und entgeht der Gerechtigkeit. Die Quest wird abgebrochen, der Wilderer bleibt ungestraft."
  T["Mikulas, the quest giver, is killed during the quest. Without him the investigation cannot be concluded and the quest is cancelled."] = "Wildhüter Nickolas, der Auftraggeber, wird während der Quest getötet. Ohne ihn lassen sich die Ermittlungen nicht abschließen, und die Quest wird abgebrochen."
  T["Enough key NPCs (Ondrej, Tomas, Marketa, and/or Radan) are killed that the investigation can no longer proceed, forcing the quest to cancel."] = "So viele wichtige NPCs (Andreas, Thomas aus dem Badehaus, Margit und/oder Radan) werden getötet, dass die Ermittlungen nicht weitergehen können; die Quest wird abgebrochen."
  T["Henry chooses to deal with Zajic through the trap option, handing the matter off to the q_zajicsTrap questline. This quest is cancelled and the follow-up quest activates."] = "Heinrich entscheidet sich, Hanekin Hase mit der Falle beizukommen, und übergibt die Sache an die Questreihe q_zajicsTrap. Diese Quest wird abgebrochen, die Folgequest startet."
  T["Henry weeds the garden flawlessly — all required herbs are present at full count and every weed is completely removed. Nicodemus is fully satisfied and awards the best reward."] = "Heinrich jätet den Garten makellos: Alle verlangten Kräuter stehen noch in voller Zahl, und jedes Unkraut ist restlos entfernt. Bruder Nicodemus ist rundum zufrieden und gibt die beste Belohnung."
  T["Henry weeds the garden adequately — the required herbs are mostly present but not at full count, or a small number of weeds remain within tolerance. Nicodemus accepts the work and gives a standard reward."] = "Heinrich jätet den Garten ordentlich: Die verlangten Kräuter sind größtenteils noch da, aber nicht in voller Zahl, oder es steht noch ein wenig Unkraut im erlaubten Rahmen. Bruder Nicodemus nimmt die Arbeit an und gibt die übliche Belohnung."
  T["Henry leaves too many weeds in the garden (any weed species exceeds 5 or combined weeds exceed 10). Nicodemus sends him back to redo the job; after three such failures the quest is failed outright."] = "Heinrich lässt zu viel Unkraut im Garten stehen (mehr als 5 von einer Unkrautart oder mehr als 10 insgesamt). Bruder Nicodemus schickt ihn zum Nachbessern zurück; nach drei solchen Fehlschlägen ist die Quest endgültig gescheitert."
  T["Henry picks so many of the required medicinal herbs that fewer than 95 of the expected 105 remain in the garden. The work is considered a catastrophic failure and the quest ends badly."] = "Heinrich rupft so viele der benötigten Heilkräuter aus, dass von den erwarteten 105 weniger als 95 im Garten bleiben. Die Arbeit gilt als völliger Fehlschlag, und die Quest endet schlecht."
  T["The NPC Nikodem (Nicodemus) is killed before the quest concludes. The quest is immediately cancelled with no reward."] = "Bruder Nicodemus wird getötet, bevor die Quest abgeschlossen ist. Die Quest wird sofort abgebrochen, ohne Belohnung."
  T["Henry finds the runaway horse Pie, rides it back to the stable parking area, dismounts it there, then collects his reward from the groom. The quest ends successfully with full payment."] = "Heinrich findet das ausgebüxte Pferd Krapfen, reitet es zurück zum Abstellplatz an den Stallungen, steigt dort ab und holt sich beim Stallmeister seine Belohnung. Die Quest endet erfolgreich mit voller Bezahlung."
  T["Henry fails to return the horse before the quest timer runs out, causing the quest to be cancelled automatically."] = "Heinrich bringt das Pferd nicht zurück, bevor der Quest-Timer abläuft; die Quest wird automatisch abgebrochen."
  T["The head groom dies during the quest, making it impossible to complete, and the quest is cancelled."] = "Der Stallmeister stirbt während der Quest. Sie lässt sich nicht mehr abschließen und wird abgebrochen."
  T["The horse Pie is killed during the quest, making return impossible and causing the quest to be cancelled."] = "Das Pferd Krapfen wird während der Quest getötet. Es kann nicht mehr zurückgebracht werden, und die Quest wird abgebrochen."
  T["Henry uses the 'possess horse' action to claim Pie as his own rather than returning it, which is treated as theft and cancels the quest."] = "Heinrich nimmt Krapfen mit der Aktion „Pferd in Besitz nehmen“ für sich, statt es zurückzubringen. Das gilt als Diebstahl und bricht die Quest ab."
  T["Henry is knocked unconscious near Bodlak during the quest, causing all NPCs to be repositioned and the quest to be cancelled."] = "Heinrich wird während der Quest in der Nähe des Köhlers bewusstlos geschlagen. Alle NPCs werden neu platziert, und die Quest wird abgebrochen."
  T["Henry successfully accompanies Ptacek on the hunting trip, rescues him from the Cumans after the boar hunt goes wrong, and the two share a closing dialog at camp. The quest ends normally with the cleanup and optional revenge sub-quest unlocked."] = "Heinrich begleitet Herrn Hans Capon auf die Jagd, rettet ihn vor den Kumanen, als die Wildschweinjagd schiefgeht, und die beiden führen im Lager ein abschließendes Gespräch. Die Quest endet regulär; der Aufräumschritt läuft, und die optionale Rache-Unterquest wird freigeschaltet."
  T["Henry sneaks into the Cuman camp without killing both guards and frees Ptacek covertly. The quest still resolves with the closing dialog and cleanup, but Henry avoided open combat."] = "Heinrich schleicht sich ins Lager der Kumanen, ohne beide Wachen zu töten, und befreit Herrn Hans Capon heimlich. Die Quest endet trotzdem mit dem abschließenden Gespräch und dem Aufräumschritt, aber Heinrich hat den offenen Kampf vermieden."
  T["Henry abandons the wounded Ptacek and flees too far from the Cuman camp, triggering a game-over cutscene. Ptacek is left to die and the quest fails."] = "Heinrich lässt den verwundeten Herrn Hans Capon im Stich und flieht zu weit vom Lager der Kumanen weg; das löst eine Game-Over-Zwischensequenz aus. Capon bleibt zum Sterben zurück, und die Quest scheitert."
  T["Henry recovers the stolen silver from Carter (by persuasion or force) and returns it to Miller Simon, who rewards him and the quest ends with Simon's closing dialogue."] = "Heinrich holt sich das gestohlene Silber vom Fuhrmann zurück (mit Überredung oder Gewalt) und bringt es Müller Simon. Der belohnt ihn, und die Quest endet mit Simons abschließendem Gespräch."
  T["Henry kills Carter to take the silver rather than letting him surrender it, completing killCarter and then delivering the silver to Simon."] = "Heinrich tötet den Fuhrmann und nimmt sich das Silber, statt es sich aushändigen zu lassen. Damit ist killCarter erledigt; danach bringt er das Silber zu Müller Simon."
  T["Henry infiltrates Vranik, rescues Zbysek, and both escape together. Henry returns to Rataj with Zbysek and reports to Radzig's men, completing the mission successfully."] = "Heinrich schleust sich in Wranik ein, befreit Bischek, und beide fliehen gemeinsam. Heinrich kehrt mit Bischek nach Rattay zurück und erstattet den Männern von Herrn Radzig Kobyla Bericht; der Auftrag ist erfolgreich erfüllt."
  T["Henry escapes from Vranik but Zbysek refuses to come or is left behind. Henry returns to Rataj alone and reports without the prisoner."] = "Heinrich entkommt aus Wranik, aber Bischek weigert sich mitzukommen oder bleibt zurück. Heinrich kehrt allein nach Rattay zurück und erstattet ohne den Gefangenen Bericht."
  T["Henry visits Lukesh's hideout and brings him the iron ration he needs, completing the quest successfully. Lukesh is relieved and the quest ends on good terms."] = "Heinrich sucht das Versteck des Schwarzen Lukesch auf und bringt ihm die eiserne Reserve, die er braucht. Die Quest ist erfolgreich abgeschlossen; Lukesch ist erleichtert, und man trennt sich im Guten."
  T["Lukesh dies before Henry can deliver the ration, causing the quest to be cancelled with no resolution. The quest fails and is abandoned."] = "Der Schwarze Lukesch stirbt, bevor Heinrich ihm die eiserne Reserve bringen kann. Die Quest wird ohne Auflösung abgebrochen: Sie ist gescheitert und wird aufgegeben."
  T["Henry and the Bohemian soldiers successfully repel the Cuman attack at the bridge and stream, completing the battle and triggering the final victory cutscene. The quest concludes with the signal to the defence quest."] = "Heinrich und die böhmischen Soldaten schlagen den Angriff der Kumanen an Brücke und Bach zurück. Die Schlacht ist gewonnen, und die abschließende Siegessequenz läuft. Die Quest endet mit dem Signal an die Verteidigungsquest."
  T["Too many Bohemian soldiers are killed during the skirmish (fewer than 6 alive in v1, fewer than 2 in v2), causing a Game Over with reason LostABattle."] = "Im Gefecht fallen zu viele böhmische Soldaten (weniger als 6 Überlebende in v1, weniger als 2 in v2); das führt zu einem Game Over mit dem Grund LostABattle."
  T["Henry leaves the designated battlefield area during the v2 battle phase, triggering an immediate Game Over with reason Q_IR_FledBattle."] = "Heinrich verlässt in der Schlachtphase von v2 das vorgesehene Schlachtfeld; das löst sofort ein Game Over mit dem Grund Q_IR_FledBattle aus."
  T["Henry ignores the call to battle and the failTimeout objective is cancelled (time runs out), triggering a Game Over with reason Q_IR_IgnoredBattle."] = "Heinrich ignoriert den Ruf zur Schlacht, und die Aufgabe failTimeout wird abgebrochen (die Zeit läuft ab); das löst ein Game Over mit dem Grund Q_IR_IgnoredBattle aus."
  T["Henry steals all three items (bag, scarf, tinderbox) for the jealous groom and delivers them, allowing the groom to spread damaging gossip about his rival. The groom then leaves the area."] = "Heinrich stiehlt für den eifersüchtigen Knecht alle drei Gegenstände (Schutzamulett, Schal, Zunderbüchse) und bringt sie ihm. So kann der Knecht üble Gerüchte über seinen Rivalen verbreiten. Danach verlässt er die Gegend."
  T["The groom dies before the quest can be completed, causing the quest to be cancelled outright."] = "Der Knecht stirbt, bevor die Quest abgeschlossen werden kann; die Quest wird sofort abgebrochen."
  T["Henry gathers the required ingredients, has the herbwoman brew a poison, places it in the cow's feed, and waits for the cow to die. The quest ends with the cow dead by poison."] = "Heinrich sammelt die nötigen Zutaten, lässt das Kräuterweib ein Gift brauen, mischt es ins Futter der Kuh und wartet, bis sie stirbt. Die Quest endet mit der vergifteten, toten Kuh."
  T["Henry secures Konrad Kyeser's release through legitimate or clever means, escorts him safely to Talmberk, and reports to Fejfar. Pejchar is dealt with before reaching Talmberk."] = "Heinrich erwirkt auf rechtmäßigem oder geschicktem Weg die Freistellung von Konrad Kyeser, geleitet ihn sicher nach Talmberg und erstattet Tobias Feyfar Bericht. Die Sache mit Peychar ist schon vor der Ankunft in Talmberg erledigt."
  T["Kyeser reaches Talmberk but Pejchar catches up and must be killed near the camp; Kyeser is angry about the violence but the quest concludes."] = "Konrad Kyeser erreicht Talmberg, doch Peychar holt sie ein und muss in der Nähe des Lagers getötet werden. Kyeser ist über die Gewalt verärgert, aber die Quest wird abgeschlossen."
  T["Henry beats Kyeser into submission and forcibly drags him to Talmberk rather than convincing him to go willingly."] = "Heinrich prügelt Konrad Kyeser gefügig und schleppt ihn mit Gewalt nach Talmberg, statt ihn zu überzeugen, freiwillig mitzukommen."
  T["Henry has the scribe forge travel documents for Karel to approve, bypassing the need to legitimately obtain permission for Kyeser to leave."] = "Heinrich lässt den Schreiber Reisedokumente fälschen, die Baumeister Karel absegnen soll, und umgeht so die rechtmäßige Erlaubnis für Kyesers Abreise."
  T["Henry bribes Karel or ruins him at dice to obtain approval for Kyeser's departure without forging documents."] = "Heinrich besticht Baumeister Karel oder ruiniert ihn beim Würfeln, um ohne gefälschte Dokumente die Zustimmung zu Kyesers Abreise zu bekommen."
  T["Henry helps Jan Zajic and the poachers survive the glade ambush by siding with the poachers or otherwise ensuring the soldiers are defeated, saving Zajic who then retreats to the cave. The quest completes normally and triggers the follow-on q_master_main objective."] = "Heinrich hilft Hanekin Hase und den Wilderern, den Hinterhalt auf der Lichtung zu überleben: Er stellt sich auf die Seite der Wilderer oder sorgt anders dafür, dass die Soldaten besiegt werden. Hanekin Hase ist gerettet und zieht sich in die Höhle zurück. Die Quest wird regulär abgeschlossen und löst die anschließende Aufgabe in q_master_main aus."
  T["Jan Zajic is killed during or after the glade fight. The engine detects zajicIsDead completed, clears Henry's superfaction, and immediately cancels the quest."] = "Hanekin Hase wird während oder nach dem Kampf auf der Lichtung getötet. Die Engine erkennt, dass zajicIsDead erfüllt ist, setzt Heinrichs übergeordnete Fraktion zurück und bricht die Quest sofort ab."
  T["Mikulas is killed at any point while the quest is active. The BT watches mikulasIsDead via a QuestObjectiveGate and cancels the quest unconditionally."] = "Wildhüter Nickolas wird zu irgendeinem Zeitpunkt getötet, während die Quest aktiv ist. Der Verhaltensbaum überwacht mikulasIsDead über ein QuestObjectiveGate und bricht die Quest bedingungslos ab."
  T["Black Lukes is killed before the goToField objective is started. The BT gate on lukesIsDead cancels the quest as long as goToField has not yet been reached."] = "Der Schwarze Lukesch wird getötet, bevor die Aufgabe goToField beginnt. Die Sperre im Verhaltensbaum auf lukesIsDead bricht die Quest ab, solange goToField noch nicht erreicht ist."
  T["Ondrej (the innkeeper) is killed before the returnTankardHidden hidden step is completed. The BT gate on ondrejIsDead cancels the quest while that condition holds."] = "Andreas (der Wirt) wird getötet, bevor der versteckte Schritt returnTankardHidden erledigt ist. Die Sperre im Verhaltensbaum auf ondrejIsDead bricht die Quest ab, solange diese Bedingung gilt."
  T["Henry chooses to side with the soldiers in the glade decision dialogue. The BT immediately sets Henry's superfaction to the rangers side, starts the pursuit objective in q_hareHunt, and cancels this quest."] = "Heinrich stellt sich im Entscheidungsgespräch auf der Lichtung auf die Seite der Soldaten. Der Verhaltensbaum setzt Heinrichs übergeordnete Fraktion sofort auf die Seite der Wildhüter, startet die Verfolgungsaufgabe in q_hareHunt und bricht diese Quest ab."
  T["Henry delivers Vincent's last will to Father Fabian in Sasau, ensuring the disinheritance of Elijah is properly recorded. The quest ends with the will in the parson's hands."] = "Heinrich bringt Vinzenz' Testament zu Pater Fabian nach Sasau und sorgt dafür, dass die Enterbung von Elias ordnungsgemäß festgehalten wird. Die Quest endet mit dem Testament in den Händen des Pfarrers."
  T["Henry loses or abandons the will without delivering it, and Cenek (Vincent) is still alive. The will is never delivered and Henry receives 500 groschen, presumably from Elias or as a bribe to suppress it."] = "Heinrich verliert das Testament oder lässt es liegen, ohne es abzugeben, und Vinzenz lebt noch. Das Testament kommt nie an, und Heinrich erhält 500 Groschen, vermutlich von Elias oder als Schweigegeld, damit es verschwindet."
  T["Vincent dies from illness before the will can be delivered, rendering it moot. Elias returns home to Merhojed as the heir by default."] = "Vinzenz stirbt an seiner Krankheit, bevor das Testament abgegeben werden kann; damit ist es hinfällig. Elias kehrt als gesetzlicher Erbe nach Merhojed heim."
  T["Vincent dies (by violence or other means) and Elias returns to Merhojed to claim his inheritance. The will was never successfully delivered."] = "Vinzenz stirbt (durch Gewalt oder auf andere Weise), und Elias kehrt nach Merhojed zurück, um sein Erbe anzutreten. Das Testament wurde nie abgegeben."
  T["Henry completes both reading lessons with the scribe in Uzhitz, reads both books, and returns to the scribe a second time, fully learning to read. The quest ends with the quest completed state and save_questEnded marked."] = "Heinrich absolviert beide Leselektionen beim Schreiber in Uschitze, liest beide Bücher und kehrt ein zweites Mal zum Schreiber zurück; nun kann er richtig lesen. Die Quest endet im Status „abgeschlossen“, und save_questEnded ist markiert."
  T["Henry finds Hynek in the cave, learns what he needs, and lets him go free. Hynek packs his belongings and leaves the area."] = "Heinrich findet Stinker in der Höhle, erfährt, was er wissen muss, und lässt ihn laufen. Stinker packt seine Habseligkeiten und verlässt die Gegend."
  T["Henry finds Hynek and turns him over to the authorities. Hynek is taken away to prison."] = "Heinrich findet Stinker und übergibt ihn der Obrigkeit. Stinker wird ins Gefängnis gebracht."
  T["Henry condemns Hynek to death during their confrontation, making him an enemy before the quest concludes."] = "Heinrich verurteilt Stinker bei ihrer Konfrontation zum Tode und macht ihn so zum Feind, bevor die Quest abgeschlossen ist."
  T["Hynek dies before Henry can confront him, cutting the quest short without resolution."] = "Stinker stirbt, bevor Heinrich ihn zur Rede stellen kann; die Quest endet vorzeitig ohne Auflösung."
  T["Henry never investigates Hynek's whereabouts and the quest ends without finding him, logged as an unresolved search."] = "Heinrich forscht nie nach Stinkers Verbleib, und die Quest endet, ohne dass er gefunden wird; sie wird als ungeklärte Suche verbucht."
  T["Henry acquires the forbidden book (Sufficientia) for Brother Nevlas and brings it to him. Cizek's nightly library visits are cancelled and the quest concludes after the book is handed over."] = "Heinrich beschafft für Bruder Nevlas das verbotene Buch (Sufficientia) und bringt es ihm. Die nächtlichen Bibliotheksbesuche von Novize Konstantin entfallen, und nach der Übergabe des Buchs ist die Quest abgeschlossen."
  T["Henry joins the cirkators in the cellar for a night of drinking, brings them a wine keg, and the session concludes peacefully. The quest ends with the keg delivered and the monks satisfied."] = "Heinrich schließt sich den Circatoren im Keller zu einem nächtlichen Gelage an und bringt ihnen ein Weinfass; die Runde endet friedlich. Die Quest endet mit dem gelieferten Fass und zufriedenen Mönchen."
  T["Henry discovers the monks' secret drinking and reports their misconduct to the Prior. The cirkators are angered and Jodok's involvement is exposed to monastery authority."] = "Heinrich entdeckt die heimlichen Trinkgelage der Mönche und meldet ihr Fehlverhalten dem Prior. Die Circatoren sind erbost, und die Beteiligung von Novize Joachim wird der Klosterleitung bekannt."
  T["Henry is thrown out of the monastery, either by refusing the task or being caught, and the quest ends with him expelled before resolving the monks' situation."] = "Heinrich wird aus dem Kloster geworfen, weil er den Auftrag verweigert oder erwischt wird. Die Quest endet mit seinem Rauswurf, bevor die Sache mit den Mönchen geklärt ist."
  T["Henry helps Ptacek woo Karolina successfully: delivers the letter and necklace, assists with the balcony serenade, and defends Ptacek against the butcher and his varlets. Ptacek wins the girl and the quest ends with a final cutscene."] = "Heinrich hilft Herrn Hans Capon erfolgreich, um Karolina zu werben: Er überbringt Brief und Halskette, hilft beim Ständchen unter dem Balkon und verteidigt Capon gegen den Fleischer und seine Knechte. Capon gewinnt das Mädchen, und die Quest endet mit einer abschließenden Zwischensequenz."
  T["Henry helps Ptacek through the quest but the balcony serenade or the confrontation with the butcher goes poorly, resulting in Ptacek failing to win Karolina. The quest still concludes after Henry reports back."] = "Heinrich hilft Herrn Hans Capon durch die Quest, aber das Ständchen unter dem Balkon oder die Auseinandersetzung mit dem Fleischer geht schief, und Capon gewinnt Karolina nicht. Die Quest endet trotzdem, nachdem Heinrich Bericht erstattet hat."
  T["Henry refuses to help Ptacek, kills Karolina, or kills the butcher before the climactic confrontation, causing the quest to be cancelled with nothing achieved for Ptacek."] = "Heinrich weigert sich, Herrn Hans Capon zu helfen, tötet Karolina oder tötet den Fleischer vor der entscheidenden Auseinandersetzung. Die Quest wird abgebrochen, und für Capon ist nichts erreicht."
  T["Henry arrives at Neuhof on time, investigates the massacre, interrogates all survivors, tracks the bandits to the forest, and reports back to Bernard with full findings. Bernard praises Henry and the quest concludes with a promotion cutscene."] = "Heinrich trifft rechtzeitig in Neuhof ein, untersucht das Massaker, befragt alle Überlebenden, verfolgt die Spur der Banditen bis in den Wald und erstattet Hauptmann Bernard vollständig Bericht. Bernard lobt Heinrich, und die Quest endet mit einer Zwischensequenz zu seiner Beförderung."
  T["Henry fails to reach the courtyard in time and Bernard's group rides to Neuhof without him. Henry catches up later and still participates in the investigation, but misses the initial departure."] = "Heinrich schafft es nicht rechtzeitig in den Burghof, und Hauptmann Bernards Trupp reitet ohne ihn nach Neuhof. Heinrich holt später auf und nimmt trotzdem an der Untersuchung teil, verpasst aber den Aufbruch."
  T["Zrzek leaves Neuhof before Henry can speak with him, so Henry cannot get his testimony. The quest continues but the lead on Zrzek is lost and Henry barks about his disappearance."] = "Rotschopf verlässt Neuhof, bevor Heinrich mit ihm sprechen kann, und Heinrich bekommt seine Aussage nicht. Die Quest geht weiter, aber die Spur zu Rotschopf ist verloren, und Heinrich kommentiert sein Verschwinden mit einer kurzen Bemerkung."
  T["Henry completes the main campaign, culminating in the conquest of Talmberg and the epilogue. This is the intended ending of the base game story."] = "Heinrich schließt die Hauptgeschichte ab, die in der Eroberung von Talmberg und dem Epilog gipfelt. Das ist das vorgesehene Ende der Geschichte des Hauptspiels."
  T["Henry successfully completes all three dates with Theresa, culminating in a romantic encounter in the barn. The relationship progresses naturally through conversation, activities, and mutual affection."] = "Heinrich absolviert alle drei Verabredungen mit Theresa, die in einer romantischen Begegnung in der Scheune gipfeln. Die Beziehung entwickelt sich ganz natürlich durch Gespräche, gemeinsame Unternehmungen und gegenseitige Zuneigung."
  T["Theresa dies during the quest, causing it to fail immediately. This is a catastrophic failure that ends any romantic possibility."] = "Theresa stirbt während der Quest, und die Quest scheitert sofort. Ein katastrophaler Ausgang, der jede Aussicht auf eine Romanze beendet."
  T["Henry fails to show up or leaves Theresa waiting during the first date, damaging the relationship and causing the quest to fail."] = "Heinrich erscheint nicht zur ersten Verabredung oder lässt Theresa warten. Das schadet der Beziehung, und die Quest scheitert."
  T["Henry abandons Theresa during the second date at the pub, failing to complete the evening and damaging their relationship."] = "Heinrich lässt Theresa bei der zweiten Verabredung in der Schenke sitzen, bringt den Abend nicht zu Ende und schadet ihrer Beziehung."
  T["Henry leaves Theresa before the romantic conclusion in the barn, failing to complete the final date and ending the quest unsuccessfully."] = "Heinrich verlässt Theresa vor dem romantischen Abschluss in der Scheune; die letzte Verabredung bleibt unvollendet, und die Quest endet erfolglos."
  T["Henry's poor reputation with Theresa prevents the dates from progressing. The relationship cannot advance due to low standing."] = "Heinrichs schlechter Ruf bei Theresa verhindert, dass die Verabredungen vorankommen. Bei so geringem Ansehen kann sich die Beziehung nicht weiterentwickeln."
  T["Henry loses the fight at the pub during the second date but the relationship continues. This affects rewards but doesn't end the quest."] = "Heinrich verliert bei der zweiten Verabredung die Schlägerei in der Schenke, aber die Beziehung geht weiter. Das wirkt sich auf die Belohnungen aus, beendet die Quest aber nicht."
  T["Henry wins the fight at the pub during the second date, impressing Theresa and earning a positive outcome for that portion of the quest."] = "Heinrich gewinnt bei der zweiten Verabredung die Schlägerei in der Schenke, beeindruckt Theresa und erzielt für diesen Teil der Quest ein gutes Ergebnis."
  T["Henry explores the mines, negotiates or deals with Nemoj peacefully, escorts the miners out, and reports back to Fejfar. The miners are freed and the situation is resolved without unnecessary bloodshed."] = "Heinrich erkundet die Mine, verhandelt mit Vormann Wendel oder einigt sich friedlich mit ihm, führt die Bergleute hinaus und erstattet Tobias Feyfar Bericht. Die Bergleute sind frei, und die Lage ist ohne unnötiges Blutvergießen gelöst."
  T["Nemoj is killed during the quest (either by Henry or as a scripted consequence), which cancels the exploration objectives and skips directly to reporting to Fejfar."] = "Vormann Wendel wird während der Quest getötet (von Heinrich oder als geskriptete Folge). Das bricht die Erkundungsaufgaben ab und springt direkt zum Bericht an Tobias Feyfar."
  T["Zuzana escapes from the mines during the quest, triggering a cutscene that teleports her to Pirkstein. The quest can still be completed but with this side consequence noted."] = "Zuzana entkommt während der Quest aus der Mine; eine Zwischensequenz teleportiert sie nach Pirkstein. Die Quest lässt sich trotzdem abschließen, diese Nebenfolge wird aber vermerkt."
  T["Henry discovers the treasure belongs to Brother Cizek, reports it to the prior or has Cizek arrested, resolving the quest through proper monastic authority. The quest ends after finding whose treasure it is and completing the report/arrest chain."] = "Heinrich findet heraus, dass der Schatz Novize Konstantin gehört, meldet es dem Prior oder lässt Konstantin verhaften und klärt die Sache so über die Klosterobrigkeit. Die Quest endet, sobald feststeht, wem der Schatz gehört, und Meldung oder Verhaftung abgeschlossen sind."
  T["Brother Cizek is killed during the quest, causing it to be cancelled rather than completed properly."] = "Novize Konstantin wird während der Quest getötet; die Quest wird abgebrochen statt ordnungsgemäß abgeschlossen."
  T["Henry leaves the monastery before resolving the treasure mystery, abandoning the quest."] = "Heinrich verlässt das Kloster, bevor das Rätsel um den Schatz gelöst ist, und gibt die Quest damit auf."
  T["Henry stole items from Cizek's stash and failed to return them within the allotted time, causing Cizek to become permanently hostile toward Henry."] = "Heinrich hat Gegenstände aus Novize Konstantins Versteck gestohlen und sie nicht rechtzeitig zurückgebracht. Konstantin ist Heinrich nun dauerhaft feindlich gesinnt."
  T["Cizek catches Henry sneaking out at night, confronts him, and wins the fight, looting Henry in the process."] = "Novize Konstantin erwischt Heinrich, als er sich nachts hinausschleicht, stellt ihn zur Rede und gewinnt den Kampf; dabei plündert er Heinrich aus."
  T["Henry traces the ring through the parson, merchant, and herbalist, locates and exhumes the grave, searches the body, and reports back to the blacksmith with confirmation of his wife's identity. The blacksmith finally has closure."] = "Heinrich verfolgt die Spur des Rings über den Pfarrer, den Händler und den Kräuterkundler, findet das Grab und öffnet es, durchsucht die Leiche und bestätigt dem Schmied, dass es seine Frau ist. Der Schmied kann endlich mit der Sache abschließen."
  T["Henry finds Ginger, deals with the bandits threatening him, reports to Bernard and Radzig, then convinces Ginger he can safely return to Neuhof. Ginger walks home and the quest ends happily."] = "Heinrich findet Rotschopf, kümmert sich um die Banditen, die ihn bedrohen, erstattet Hauptmann Bernard und Herrn Radzig Kobyla Bericht und überzeugt Rotschopf dann, dass er gefahrlos nach Neuhof zurückkehren kann. Rotschopf geht heim, und die Quest endet glücklich."
  T["Henry finds Ginger and reports to Bernard and Radzig, but tells Ginger he cannot return to Neuhof. Ginger leaves for parts unknown and the quest closes without a happy reunion."] = "Heinrich findet Rotschopf und erstattet Hauptmann Bernard und Herrn Radzig Kobyla Bericht, sagt Rotschopf aber, dass er nicht nach Neuhof zurückkehren kann. Rotschopf zieht ins Ungewisse davon, und die Quest endet ohne glückliches Wiedersehen."
  T["After Ginger spills the beans about the bandits, the timer expires and the bandits execute Ginger before Henry can protect him. The quest ends with Ginger dead."] = "Nachdem Rotschopf über die Banditen ausgepackt hat, läuft der Timer ab, und die Banditen richten ihn hin, bevor Heinrich ihn schützen kann. Die Quest endet mit Rotschopfs Tod."
  T["Henry collects all required herbs and delivers them to Brother Nicodemus. The quest concludes successfully with the herbarium complete."] = "Heinrich sammelt alle verlangten Kräuter und bringt sie Bruder Nicodemus. Die Quest endet erfolgreich mit dem vollständigen Herbarium."
  T["Henry gives the book to Brother Nicodemus, completing the quest via the alternative book-delivery path."] = "Heinrich gibt Bruder Nicodemus das Buch und schließt die Quest über den alternativen Weg der Buchübergabe ab."
  T["Brother Nicodemus dies before the quest is completed, causing the quest to be cancelled with no resolution."] = "Bruder Nicodemus stirbt, bevor die Quest abgeschlossen ist; die Quest wird ohne Auflösung abgebrochen."
  T["Henry and the thieves successfully rescue the captives from Talmberg, escape the castle undetected or after dealing with the wall guards, and report back to Borek. The quest ends with the final debriefing dialog."] = "Heinrich und die Diebe befreien die Gefangenen aus Talmberg, entkommen unbemerkt aus der Burg oder nachdem sie die Wachen auf der Mauer ausgeschaltet haben, und erstatten Herrn Robard Bericht. Die Quest endet mit der abschließenden Nachbesprechung."
  T["The alarm is raised and Ptacek is injured during the escape; Henry must carry or save Ptacek while fleeing the castle, then report to Borek. The quest still completes successfully but via the alarm path."] = "Alarm wird geschlagen, und Herr Hans Capon wird bei der Flucht verletzt; Heinrich muss Capon auf der Flucht aus der Burg tragen oder retten und dann Herrn Robard Bericht erstatten. Die Quest wird trotzdem erfolgreich abgeschlossen, allerdings über den Alarm-Weg."
  T["Henry is discovered and the alarm is raised before the captives are freed; the stealth mission fails but Henry and the group still manage to flee the castle and report to Borek."] = "Heinrich wird entdeckt, und Alarm wird geschlagen, bevor die Gefangenen befreit sind. Die Schleichmission scheitert, aber Heinrich und die Gruppe können trotzdem aus der Burg fliehen und Herrn Robard Bericht erstatten."
  T["Ptacek is injured and Henry fails to save him within the 240-second timer; Ptacek bleeds out and the game triggers a Game Over with reason PtacekBledOut."] = "Herr Hans Capon wird verletzt, und Heinrich kann ihn nicht innerhalb des 240-Sekunden-Timers retten. Capon verblutet, und das Spiel löst ein Game Over mit dem Grund PtacekBledOut aus."
  T["Henry abandons the mission by leaving the area before completing the objective; the toWalls objective is canceled and the game triggers a Game Over with reason NightRescueRanAway."] = "Heinrich bricht die Mission ab, indem er das Gebiet verlässt, bevor die Aufgabe erledigt ist. Die Aufgabe toWalls wird abgebrochen, und das Spiel löst ein Game Over mit dem Grund NightRescueRanAway aus."
  T["Henry commits a crime against allied NPCs during the mission and is confronted; the game triggers a Game Over with reason NightRescueCrime."] = "Heinrich begeht während der Mission ein Verbrechen an verbündeten NPCs und wird zur Rede gestellt; das Spiel löst ein Game Over mit dem Grund NightRescueCrime aus."
  T["Henry catches all three nightingales and returns them to Berthold the Huntsman, completing the quest successfully. Berthold takes the cages and the quest ends."] = "Heinrich fängt alle drei Nachtigallen und bringt sie Wildhüter Berthold; die Quest ist erfolgreich abgeschlossen. Berthold nimmt die Käfige entgegen, und die Quest endet."
  T["Berthold the Huntsman dies before Henry can return the nightingales. The quest is cancelled and all bird traps are removed."] = "Wildhüter Berthold stirbt, bevor Heinrich ihm die Nachtigallen bringen kann. Die Quest wird abgebrochen, und alle Vogelfallen werden entfernt."
  T["Henry pays off the debt to Pesek's miller, satisfying all parties. The quest ends cleanly with Pesek on good terms and the miller quests unlocked."] = "Heinrich begleicht seine Schulden bei Müller Peschek, und alle Seiten sind zufrieden. Die Quest endet sauber, Heinrich steht mit Peschek auf gutem Fuß, und die Müller-Quests sind freigeschaltet."
  T["Henry recovers the ring (from Herman or the grave) and delivers it to Vojtech, resolving the debt through the ring's value. The quest ends with the debt cleared via the ring."] = "Heinrich beschafft den Ring (von Henker Hermann oder aus dem Grab) und bringt ihn zu Müller Woyzeck; der Wert des Rings tilgt die Schulden. Die Quest endet mit den über den Ring beglichenen Schulden."
  T["Pesek or Vojtech is killed, making the quest impossible to complete. The quest is cancelled by the engine when either death is detected."] = "Müller Peschek oder Müller Woyzeck wird getötet, und die Quest lässt sich nicht mehr abschließen. Die Engine bricht sie ab, sobald sie einen der beiden Tode erkennt."
  T["Henry ignores the debt long enough that the miller timer fires twice, activating enforcers who hunt him across Rattay. Pesek becomes hostile and Henry is unwelcome at the mill."] = "Heinrich ignoriert die Schulden so lange, dass der Müller-Timer zweimal auslöst; Schuldeneintreiber machen nun in ganz Rattay Jagd auf ihn. Müller Peschek wird feindselig, und in der Mühle ist Heinrich nicht mehr willkommen."
  T["Henry successfully pickpockets the training knife from Peshek behind the mill, completes the post-theft dialogue, and the quest ends normally. This is the only intended narrative ending for this tutorial quest."] = "Heinrich stiehlt Müller Peschek hinter der Mühle erfolgreich das Übungsmesser aus der Tasche, führt das Gespräch nach dem Diebstahl, und die Quest endet regulär. Das ist das einzige vorgesehene Ende dieser Tutorial-Quest."
  T["Henry investigates the plague, obtains a cure with Nikodem's help or brews it himself, and successfully administers it to the sick villagers. Merhojed survives and the quest ends with the village recovering."] = "Heinrich untersucht die Seuche, beschafft mit Hilfe von Bruder Nicodemus ein Heilmittel oder braut es selbst und verabreicht es den kranken Dorfbewohnern. Merhojed überlebt, und die Quest endet mit einem Dorf, das sich erholt."
  T["Henry brings the cure but not all villagers survive — some die before treatment reaches them. The quest still resolves as a partial success with the village recovering."] = "Heinrich bringt das Heilmittel, aber nicht alle Dorfbewohner überleben: Einige sterben, bevor die Behandlung sie erreicht. Die Quest endet trotzdem als Teilerfolg, das Dorf erholt sich."
  T["Henry fails to bring the cure in time and all the sick villagers die. The quest ends in failure with Merhojed left as a ghost village."] = "Heinrich bringt das Heilmittel nicht rechtzeitig, und alle kranken Dorfbewohner sterben. Die Quest endet mit einem Fehlschlag, Merhojed bleibt als Geisterdorf zurück."
  T["The illness timer expires before Henry delivers the cure — either because he never spoke with Melichar or because he obtained the cure but never brought it back. The quest is cancelled and the village is lost."] = "Der Krankheits-Timer läuft ab, bevor Heinrich das Heilmittel bringt, entweder weil er nie mit Melichar gesprochen hat oder weil er das Heilmittel zwar besorgt, es aber nie zurückbringt. Die Quest wird abgebrochen, und das Dorf ist verloren."
end)
fill(function(T)
  T["Henry kills Melichar before the cure is delivered, causing the quest to be cancelled immediately. The village cannot be saved."] = "Heinrich tötet Melichar, bevor das Heilmittel gebracht ist; die Quest wird sofort abgebrochen. Das Dorf ist nicht mehr zu retten."
  T["Henry kills Nikodem before he has diagnosed the illness and pointed Henry toward Mrhojedy, making it impossible to obtain the cure. The quest is cancelled."] = "Heinrich tötet Bruder Nicodemus, bevor dieser die Krankheit erkannt und Heinrich nach Merhojed geschickt hat; so lässt sich kein Heilmittel mehr beschaffen. Die Quest wird abgebrochen."
  T["The companion quest q_captiveInMerhojed is completed before Henry ever speaks with Melichar about the plague, so the plague quest is cancelled with a note that Henry never investigated."] = "Die Begleitquest q_captiveInMerhojed wird abgeschlossen, bevor Heinrich überhaupt mit Melichar über die Seuche spricht. Die Seuchenquest wird deshalb mit dem Vermerk abgebrochen, dass Heinrich nie ermittelt hat."
  T["Henry and the Skalitz survivors successfully storm Pribyslawitz, defeat the Cuman boss and bandit boss Runt, and liberate the village. The quest ends with the post-battle cutscene and Istvan watching over the reclaimed settlement."] = "Heinrich und die Überlebenden aus Skalitz stürmen Pribyslawitz, besiegen den Anführer der Kumanen und den Banditenanführer Wicht und befreien das Dorf. Die Quest endet mit der Zwischensequenz nach der Schlacht, in der Herr Istvan Toth über die zurückeroberte Siedlung wacht."
  T["Henry leaves the battle area before the fighting is resolved, abandoning his allies. This triggers a Game Over with the reason 'FledBattle'."] = "Heinrich verlässt das Schlachtfeld, bevor der Kampf entschieden ist, und lässt seine Verbündeten im Stich. Das löst ein Game Over mit dem Grund „FledBattle“ aus."
  T["Too many friendly soldiers are killed during the battle, causing the assault to collapse. This triggers a Game Over with the reason 'TooManyCasualties'."] = "In der Schlacht fallen zu viele verbündete Soldaten, und der Angriff bricht zusammen. Das löst ein Game Over mit dem Grund „TooManyCasualties“ aus."
  T["Henry is killed during the battle. This triggers a Game Over with the reason 'LostABattle'."] = "Heinrich fällt in der Schlacht. Das löst ein Game Over mit dem Grund „LostABattle“ aus."
  T["Henry scouts the bandit camp at Pribyslav, reports to Borek, gathers reinforcements, and leads the assault that retakes the fortified camp. The quest concludes with the battle preparation complete."] = "Heinrich kundschaftet das Banditenlager bei Pribyslawitz aus, erstattet Herrn Robard Bericht, sammelt Verstärkung und führt den Angriff an, der das befestigte Lager zurückerobert. Die Quest endet mit abgeschlossenen Schlachtvorbereitungen."
  T["Henry wins the Rattay sword tournament. The quest completes successfully and he can collect his prize money and a special item or weapon from the tournament organizer."] = "Heinrich gewinnt das Rattayer Turnier. Die Quest ist erfolgreich abgeschlossen, und er kann beim Veranstalter sein Preisgeld und einen besonderen Gegenstand oder eine Waffe abholen."
  T["Henry loses the tournament or is disqualified (e.g. by committing a crime in the arena area). The quest is cancelled with no reward."] = "Heinrich verliert das Turnier oder wird disqualifiziert (z. B. weil er auf dem Kampfplatz ein Verbrechen begeht). Die Quest wird ohne Belohnung abgebrochen."
  T["Henry joins Bernard's assault on Wolflin's camp. Bernard's forces win the battle, Wolflin is killed, and Henry returns to Hanus to collect his reward."] = "Heinrich schließt sich Hauptmann Bernards Angriff auf das Lager von Herrn Wolflin von Kamberg an. Bernards Truppen gewinnen die Schlacht, Wolflin wird getötet, und Heinrich kehrt zu Herrn Hanusch von Leipa zurück, um seine Belohnung abzuholen."
  T["Henry joins the assault but Bernard's forces lose the battle. Henry must retreat back to Bernard's camp in defeat."] = "Heinrich schließt sich dem Angriff an, doch Hauptmann Bernards Truppen verlieren die Schlacht. Heinrich muss sich geschlagen in Bernards Lager zurückziehen."
  T["Henry infiltrates Wolflin's camp disguised and negotiates a peaceful resolution, convincing Wolflin to stand down without bloodshed."] = "Heinrich schleicht sich verkleidet in das Lager von Herrn Wolflin von Kamberg und handelt eine friedliche Lösung aus: Er überzeugt Wolflin, ohne Blutvergießen aufzugeben."
  T["Diplomacy breaks down and Wolflin challenges Henry to a duel; Henry wins the duel, killing Wolflin, then reports back to Bernard and returns to Hanus."] = "Die Verhandlungen scheitern, und Herr Wolflin von Kamberg fordert Heinrich zum Duell. Heinrich gewinnt und tötet Wolflin, erstattet dann Hauptmann Bernard Bericht und kehrt zu Herrn Hanusch von Leipa zurück."
  T["Henry loses the duel with Wolflin and flees the area; he must return to Bernard's camp having failed to resolve the situation."] = "Heinrich verliert das Duell gegen Herrn Wolflin von Kamberg und flieht; er muss in Hauptmann Bernards Lager zurückkehren, ohne die Lage gelöst zu haben."
  T["Wolflin was killed before Henry joined Bernard's campaign; the quest acknowledges this and Henry proceeds to report back and collect the reward."] = "Herr Wolflin von Kamberg wurde getötet, bevor Heinrich sich Hauptmann Bernards Feldzug angeschlossen hat. Die Quest berücksichtigt das, und Heinrich kann gleich Bericht erstatten und die Belohnung abholen."
  T["Henry investigates the illegal press-gang operation in Sasau, attends the midnight mass at the church to witness the recruiters in action, and completes the quest by going to meet the recruiters. The criminal operation is exposed and dealt with."] = "Heinrich untersucht das illegale Treiben der Presser in Sasau, besucht die Mitternachtsmesse in der Kirche, um die Anwerber in Aktion zu sehen, und schließt die Quest ab, indem er sich mit ihnen trifft. Das kriminelle Treiben fliegt auf und wird beendet."
  T["Henry returns to Skalitz, finds his parents' bodies, buries them, deals with Zbysek, fights Runt's man Prcek, and retrieves his father's sword. The quest ends with Henry leaving Skalitz having honoured his parents."] = "Heinrich kehrt nach Skalitz zurück, findet die Leichen seiner Eltern und begräbt sie, rechnet mit Bischek ab, kämpft gegen Wicht und seine Leute und holt sich das Schwert seines Vaters zurück. Die Quest endet damit, dass Heinrich Skalitz verlässt, nachdem er seinen Eltern die letzte Ehre erwiesen hat."
  T["Henry follows the main story from Skalitz through every major chapter — Neuhof, Auschitz, Ledetchko, Timmy, Nest of Vipers, Baptism of Fire, the aftermath of Pribyslawitz, the counterfeiters, infiltration, the counter-offensive, retaking Talmberg, and finally the epilogue. This is the single linear ending of the overarching revenge quest."] = "Heinrich folgt der Hauptgeschichte von Skalitz aus durch alle großen Kapitel: Neuhof, Uschitze, Ledetschko, Timmy, „Schlangennest“, „Feuertaufe“, die Ruhe nach dem Sturm in Pribyslawitz, die Falschmünzer, die Unterwanderung, die Gegenoffensive, die Rückeroberung von Talmberg und schließlich der Epilog. Das ist das einzige, lineare Ende der übergreifenden Rachequest."
  T["Henry rides with Kuno's band through all chapters — prologue, message, feast, trap, traitor, and battle — completing the full questline. The quest ends normally after the final battle."] = "Heinrich reitet mit Kunos Männern durch alle Kapitel (Prolog, Botschaft, Festmahl, Falle, Verräter und Schlacht) und schließt die gesamte Questreihe ab. Die Quest endet regulär nach der letzten Schlacht."
  T["Kuno is killed at any point during the quest. His death triggers the destroy objective which cancels the quest (unless the battle sub-quest has the ignoreKunosDeath flag set)."] = "Herr Kuno wird zu irgendeinem Zeitpunkt der Quest getötet. Sein Tod löst die Aufgabe „destroy“ aus, die die Quest abbricht (außer in der Schlacht-Unterquest ist das Flag ignoreKunosDeath gesetzt)."
  T["One or more of Kuno's band members (Jan Brtnik, Petr Brtnik, Provaznik, Stepan, or Nemec) is killed, triggering the oneOfKunobandIsDead chain."] = "Einer oder mehrere von Kunos Männern (Jan Bärmann, Petr Bärmann, Baumler, Stepan Fieder oder Der Stein) werden getötet; das löst die Kette oneOfKunobandIsDead aus."
  T["Henry successfully passes the ring through the full chain of Kunoband members — Provaznik, Nemec, Stepan, Jan, Petr — and finally delivers it to Kuno, completing the Bacchus drinking game ritual. The quest ends with the ring in Kuno's hands and the band satisfied."] = "Heinrich reicht den Ring durch die ganze Reihe von Kunos Männern weiter (Baumler, Der Stein, Stepan Fieder, Jan Bärmann, Petr Bärmann) und übergibt ihn schließlich Herrn Kuno; damit ist das Trinkritual des Bacchus vollzogen. Die Quest endet mit dem Ring in Kunos Händen und einer zufriedenen Bande."
  T["The quest is forcibly cancelled because a member of Kunoband dies, the band leaves camp prematurely, or Kuno betrays the group (cs_kunoLeaves in q_rides_battle fires). The ring ritual can never be completed and the quest is abandoned."] = "Die Quest wird zwangsweise abgebrochen, weil einer von Kunos Männern stirbt, die Bande das Lager vorzeitig verlässt oder Herr Kuno die Gruppe verrät (cs_kunoLeaves in q_rides_battle löst aus). Das Ringritual lässt sich nie mehr vollenden, und die Quest wird aufgegeben."
  T["Kuno agrees to stay and fight alongside Henry. The two sides clash in a full skirmish, Hagen's band is defeated, and Henry reports the outcome to Sir Radzig."] = "Herr Kuno willigt ein, zu bleiben und an Heinrichs Seite zu kämpfen. Beide Seiten prallen in einem offenen Gefecht aufeinander, Herr Hagens Bande wird besiegt, und Heinrich berichtet Herrn Radzig Kobyla vom Ausgang."
  T["Kuno is bribed or persuaded to leave, so Henry faces Hagen alone in a duel. Henry defeats Hagen (knocks him unconscious or forces surrender) and then reports to Sir Radzig."] = "Herr Kuno wird bestochen oder überredet abzuziehen, also tritt Heinrich allein im Duell gegen Herrn Hagen Zul an. Heinrich besiegt Hagen (schlägt ihn bewusstlos oder zwingt ihn, sich zu ergeben) und erstattet dann Herrn Radzig Kobyla Bericht."
  T["Kuno leaves and Henry duels Hagen one-on-one, but kills him outright instead of sparing him. Hagen's band turns hostile and Henry must deal with the fallout before reporting to Radzig."] = "Herr Kuno zieht ab, und Heinrich kämpft Mann gegen Mann gegen Herrn Hagen Zul, tötet ihn aber, statt ihn zu verschonen. Herr Hagens Bande wird feindselig, und Heinrich muss mit den Folgen fertigwerden, bevor er Herrn Radzig Kobyla Bericht erstattet."
  T["Henry violates the agreed terms of the duel or battle (attacking outside the rules), causing Hagen's men to turn hostile and drive him off the field. The quest ends in disgrace."] = "Heinrich bricht die vereinbarten Regeln des Duells oder der Schlacht (er greift regelwidrig an); die Männer von Herrn Hagen Zul werden feindselig und vertreiben ihn vom Feld. Die Quest endet mit Schande."
  T["Kuno is killed during the skirmish, cutting the battle short. Henry must still report to Sir Radzig, but the loss of Kuno is a significant failure."] = "Herr Kuno fällt im Gefecht, und die Schlacht endet vorzeitig. Heinrich muss Herrn Radzig Kobyla trotzdem Bericht erstatten, aber Kunos Verlust ist ein schwerer Fehlschlag."
  T["Henry joins Kuno's band at the mill for the feast, participates in the fun (drinking, fighting, stories), and the group returns to camp together after the night ends. The quest concludes when kunoband_leave completes and the 'end' objective fires."] = "Heinrich schließt sich Kunos Männern zum Festmahl an der Mühle an, macht beim Vergnügen mit (Trinken, Raufen, Geschichten), und nach der Nacht kehrt die Gruppe gemeinsam ins Lager zurück. Die Quest endet, wenn kunoband_leave erfüllt ist und die Aufgabe „end“ auslöst."
  T["Henry follows Kuno's band to the burned farm, investigates the attack, tracks down the bandits on the glade, helps defeat them, and reports the findings (letter and shield as evidence) to Racek. The quest ends successfully with the codex entry about Zoul unlocked."] = "Heinrich folgt Kunos Männern zum niedergebrannten Hof, untersucht den Überfall, spürt die Banditen auf der Lichtung auf, hilft, sie zu besiegen, und legt Herrn Radzig Kobyla seine Erkenntnisse vor (Brief und Schild als Beweise). Die Quest endet erfolgreich, und der Kodexeintrag „Familie Zul von Ostředek“ wird freigeschaltet."
  T["Kuno is killed during the quest, which causes the quest to be immediately cancelled via CancelQuest. The quest fails and cannot be completed."] = "Herr Kuno wird während der Quest getötet; die Quest wird sofort über CancelQuest abgebrochen. Sie ist gescheitert und lässt sich nicht abschließen."
  T["Henry defeats the fighter convincingly, impressing Kuno. After the fight evaluation dialogue, Henry is invited to join Kuno's band."] = "Heinrich besiegt den Kämpfer überzeugend und beeindruckt Herrn Kuno. Nach dem Gespräch, in dem der Kampf bewertet wird, lädt man Heinrich ein, sich Kunos Männern anzuschließen."
  T["Henry loses the fight but performs well enough (health delta 0-15) that Kuno still invites him to join the band."] = "Heinrich verliert den Kampf, schlägt sich aber gut genug (Gesundheitsdifferenz 0-15), dass Herr Kuno ihn trotzdem in die Bande einlädt."
  T["Henry loses the fight badly (health delta >15), failing to impress Kuno. The quest ends without Henry joining the band."] = "Heinrich verliert den Kampf deutlich (Gesundheitsdifferenz >15) und kann Herrn Kuno nicht beeindrucken. Die Quest endet, ohne dass Heinrich in die Bande aufgenommen wird."
  T["Kuno dies before or during the quest, causing it to be cancelled immediately."] = "Herr Kuno stirbt vor oder während der Quest, und die Quest wird sofort abgebrochen."
  T["Henry tracks down Jakey (Kubajs), defeats him in combat, and has him taken to prison. The quest ends with Kubajs surrendering and being escorted away."] = "Heinrich spürt Jackel auf, besiegt ihn im Kampf und lässt ihn ins Gefängnis bringen. Die Quest endet damit, dass Jackel sich ergibt und abgeführt wird."
  T["Kubajs knocks Henry unconscious during the confrontation and flees the area, escaping justice entirely."] = "Jackel schlägt Heinrich bei der Konfrontation bewusstlos und flieht; er entgeht der Gerechtigkeit vollständig."
  T["Henry questions Kubajs but ultimately leaves him tied up and walks away without resolving his fate, logging the outcome as abandoned."] = "Heinrich verhört Jackel, lässt ihn am Ende aber gefesselt zurück und geht, ohne über sein Schicksal zu entscheiden; der Ausgang wird als aufgegeben verbucht."
  T["Kubajs is killed during the quest, either before Henry can question him or during the confrontation, logging his death as the final outcome."] = "Jackel wird während der Quest getötet, bevor Heinrich ihn verhören kann oder bei der Konfrontation; sein Tod wird als endgültiger Ausgang verbucht."
  T["The merchant Arnost dies before Henry can complete the investigation, cancelling the girl rescue thread and cutting off the normal quest resolution path."] = "Händler Ernst stirbt, bevor Heinrich die Ermittlungen abschließen kann. Der Handlungsstrang um die Rettung des Mädchens wird abgebrochen, und der normale Weg zum Abschluss der Quest ist versperrt."
  T["Henry and Kuno's band survive the ambush and fight off the attackers. Henry speaks with Kuno after the battle, completing the quest successfully."] = "Heinrich und Kunos Männer überleben den Hinterhalt und schlagen die Angreifer zurück. Heinrich spricht nach dem Kampf mit Herrn Kuno, und die Quest ist erfolgreich abgeschlossen."
  T["Henry and Kuno survive the ambush but Henry does not speak with Kuno in time; the post-fight conversation times out and the quest ends."] = "Heinrich und Herr Kuno überleben den Hinterhalt, aber Heinrich spricht nicht rechtzeitig mit Kuno; das Gespräch nach dem Kampf verfällt, und die Quest endet."
  T["The fight is lost or times out and Kuno is still alive but on the ground; the quest ends in failure with Kuno incapacitated."] = "Der Kampf geht verloren oder die Zeit läuft ab, und Herr Kuno lebt noch, liegt aber am Boden; die Quest scheitert, Kuno ist kampfunfähig."
  T["The fight is lost or times out and Kuno dies during the ambush; the quest ends in failure with Kuno's death."] = "Der Kampf geht verloren oder die Zeit läuft ab, und Herr Kuno stirbt im Hinterhalt; die Quest scheitert mit Kunos Tod."
  T["Henry regularly visits Theresa, walks with her, and the relationship deepens into something more. Theresa is calm and receptive, and Henry may optionally bring her a dress as a gift."] = "Heinrich besucht Theresa regelmäßig, geht mit ihr spazieren, und die Beziehung vertieft sich zu mehr. Theresa ist ruhig und zugewandt, und Heinrich kann ihr auf Wunsch ein Kleid schenken."
  T["Henry fails to visit Theresa for several days after their first meeting, causing her to become angry and the relationship to sour."] = "Heinrich besucht Theresa nach ihrem ersten Treffen mehrere Tage lang nicht; sie wird wütend, und die Beziehung trübt sich."
  T["Henry learns the bandit camp location (from Peta, Mach, or by accident) and reports it to the relevant party, completing the quest and unlocking the Nest of Vipers follow-up."] = "Heinrich erfährt, wo das Banditenlager liegt (von Timmy, von Morcock oder durch Zufall), und meldet es an der richtigen Stelle. Die Quest ist abgeschlossen, und die Folgequest „Schlangennest“ wird freigeschaltet."
  T["Henry stumbles upon the bandit camp on his own and reports its location without needing Peta or Mach's help."] = "Heinrich stößt auf eigene Faust auf das Banditenlager und meldet dessen Lage, ohne Hilfe von Timmy oder Morcock zu brauchen."
  T["Henry follows Mach back to the bandit camp directly, with Mach revealing the location himself, then reports it."] = "Heinrich folgt Morcock direkt zurück zum Banditenlager, sodass Morcock die Lage selbst verrät, und meldet sie dann."
  T["The bandits find Peta and kill her before Henry can protect her, resulting in a darker resolution where the bandits are grateful to Henry for leading them to her."] = "Die Banditen finden Timmy und töten sie, bevor Heinrich sie schützen kann. Ein düsteres Ende: Die Banditen sind Heinrich dankbar, dass er sie zu ihr geführt hat."
  T["Henry kills Peta himself, either during a brawl or deliberately, cutting short her ability to provide information."] = "Heinrich tötet Timmy selbst, in einer Rauferei oder mit Absicht; damit kann sie keine Auskunft mehr geben."
  T["Mach is killed during the quest, canceling his ability to lead Henry to the camp or pay a reward, and forcing Henry to find another path or abandon that route."] = "Morcock wird während der Quest getötet. Er kann Heinrich nicht mehr zum Lager führen oder eine Belohnung zahlen; Heinrich muss einen anderen Weg finden oder diesen aufgeben."
  T["Mirka dies before Henry can get information about Peta's whereabouts from her, triggering a fallback hint and blocking the normal investigation path."] = "Mirka stirbt, bevor Heinrich von ihr erfahren kann, wo Timmy steckt. Das löst einen Ersatzhinweis aus und versperrt den normalen Weg der Ermittlungen."
  T["Henry completes the tracker quest by reaching the end objective. The quest serves as a background tracker that activates related quests (q_samopesh, q_pribyslav) when the bandit camp is found by accident."] = "Heinrich schließt die Tracker-Quest ab, indem er die Aufgabe „end“ erreicht. Die Quest dient als Tracker im Hintergrund, der verwandte Quests (q_samopesh, q_pribyslav) aktiviert, wenn das Banditenlager zufällig gefunden wird."
  T["Henry stumbles upon the bandit camp by accident, triggering activation of the q_samopesh and q_pribyslav quests if they are not already started, and starting the findBanditCampByAccident objective in q_samopesh."] = "Heinrich stößt zufällig auf das Banditenlager. Das aktiviert die Quests q_samopesh und q_pribyslav, falls sie noch nicht laufen, und startet die Aufgabe findBanditCampByAccident in q_samopesh."
  T["Henry completes his undercover stay at the monastery, fulfilling his duties and gathering information. The quest ends normally after the main story objective (Antonin going to jail or the saint investigation concluding) is resolved."] = "Heinrich bringt seinen verdeckten Aufenthalt im Kloster zu Ende, erfüllt seine Pflichten und sammelt Informationen. Die Quest endet regulär, sobald die Aufgabe der Hauptgeschichte erledigt ist (Novize Antonius kommt ins Gefängnis, oder die Suche nach Pius ist abgeschlossen)."
  T["Henry accumulates too many rule violations and is expelled from the monastery, cancelling the quest. He is kicked out via cutscene and loses access to the monastery."] = "Heinrich sammelt zu viele Regelverstöße an und wird aus dem Kloster verwiesen; die Quest wird abgebrochen. Eine Zwischensequenz zeigt seinen Rauswurf, und er hat keinen Zutritt mehr zum Kloster."
  T["One of the key apprentice monks (Antonin, Cizek, Lukas, or Jodok) is killed during the quest, forcing it to end prematurely. The side quests are cancelled and the quest concludes via endQuest."] = "Einer der wichtigen Novizen (Novize Antonius, Novize Konstantin, Novize Lukas oder Novize Joachim) wird während der Quest getötet, und sie endet vorzeitig. Die Nebenquests werden abgebrochen, und die Quest endet über endQuest."
  T["The linked quest q_searchForSaint reaches a conclusion (Antonin goes to jail or Henry kills the saint and leaves the monastery), which triggers this quest to end. Henry retrieves his belongings and the monastery chapter closes."] = "Die verknüpfte Quest q_searchForSaint kommt zum Abschluss (Novize Antonius kommt ins Gefängnis, oder Heinrich tötet Pius und verlässt das Kloster), und das beendet diese Quest. Heinrich holt seine Habseligkeiten zurück, und das Kapitel im Kloster ist abgeschlossen."
  T["Henry defeats Antonin in the duel triggered by the bailiff confrontation, and Antonin is taken to jail in Rataje. The true saint is exposed and justice is served through lawful means."] = "Heinrich besiegt Novize Antonius im Duell, zu dem es bei der Konfrontation mit dem Vogt kommt, und Antonius wird in Rattay ins Gefängnis gebracht. Der wahre Pius ist entlarvt, und der Gerechtigkeit wird auf rechtmäßigem Weg Genüge getan."
  T["Henry kills Antonin directly (or kills the apprentice, or uses the killSaint objective), bypassing any lawful resolution. The quest ends with Antonin dead at Henry's hand."] = "Heinrich tötet Novize Antonius kurzerhand (oder tötet den Novizen bzw. nutzt die Aufgabe killSaint) und umgeht jede rechtmäßige Lösung. Die Quest endet mit Antonius' Tod durch Heinrichs Hand."
  T["Henry defeats Antonin in the duel after Antonin escapes to the bandits, killing him in the process. The quest ends with Antonin dead but through a forced confrontation rather than lawful arrest."] = "Novize Antonius flieht zu den Banditen; Heinrich besiegt ihn im Duell und tötet ihn dabei. Die Quest endet mit Antonius' Tod, allerdings durch eine erzwungene Konfrontation statt einer rechtmäßigen Festnahme."
  T["Henry declines Antonin's offer and fights him; if Antonin is beaten he is killed and the quest ends, but if Henry loses it is game over. Antonin dies without proper justice."] = "Heinrich lehnt das Angebot von Novize Antonius ab und kämpft gegen ihn. Wird Antonius besiegt, stirbt er, und die Quest endet; verliert Heinrich, ist das Spiel vorbei. Antonius stirbt ohne ordentliches Verfahren."
  T["Henry fails to confront Antonin in time after the escape cutscene; the antoninRunAway_timer expires, Antonin flees the monastery entirely and is cleared from the world, leaving the quest unresolved."] = "Heinrich stellt Novize Antonius nach der Fluchtsequenz nicht rechtzeitig; antoninRunAway_timer läuft ab, Antonius flieht endgültig aus dem Kloster und wird aus der Welt entfernt. Die Quest bleibt ungelöst."
  T["Henry successfully learns the Sasau blacksmith's tempering ditty, reports back to the Ledetchko blacksmith with the correct verse, and receives a high reward. The quest ends cleanly with full completion."] = "Heinrich lernt die Verslein, mit denen der Sasauer Schmied das Härten abpasst, trägt dem Ledetschkoer Schmied die richtigen Verse vor und erhält eine hohe Belohnung. Die Quest endet sauber und vollständig erfüllt."
  T["Henry reports back to the Ledetchko blacksmith but fails the speech check or delivers an imperfect account, receiving only a low reward before the quest ends."] = "Heinrich erstattet dem Ledetschkoer Schmied Bericht, scheitert aber an der Redekunst-Probe oder gibt die Verse unvollständig wieder und erhält nur eine geringe Belohnung, bevor die Quest endet."
  T["Henry's initial report to the Ledetchko blacksmith fails the poem check, but he corrects it via fixReport and still completes the quest."] = "Heinrichs erster Bericht an den Ledetschkoer Schmied besteht die Prüfung der Verse nicht, doch er berichtigt ihn über fixReport und schließt die Quest trotzdem ab."
  T["One or both smiths die during the quest, causing all active objectives to be cancelled and the quest to fail without resolution."] = "Einer oder beide Schmiede sterben während der Quest. Alle aktiven Aufgaben werden abgebrochen, und die Quest scheitert ohne Auflösung."
  T["Henry completes all his errands, helps his father forge the sword, and receives it before the Cumans attack Skalitz. This is the intended successful completion of the prologue."] = "Heinrich erledigt alle seine Besorgungen, hilft seinem Vater, das Schwert zu schmieden, und erhält es, bevor die Kumanen Skalitz überfallen. Das ist der vorgesehene erfolgreiche Abschluss des Prologs."
  T["Henry retrieves the nails from the chest and delivers them to Tereza, ending the quest via the alternate nail-delivery path rather than receiving the sword directly."] = "Heinrich holt die Nägel aus der Truhe und bringt sie Theresa; die Quest endet über den alternativen Weg der Nagellieferung, statt dass er das Schwert direkt erhält."
  T["Henry fights Ota fairly and wins the duel, then collects his reward from Zach the blacksmith. Zach's armour is vindicated and Henry earns his pay as champion."] = "Heinrich kämpft fair gegen Meister Otto und gewinnt das Duell; danach holt er sich seine Belohnung beim Schmied Zach. Zachs Rüstung hat sich bewährt, und Heinrich verdient seinen Lohn als Streiter."
  T["Henry accepts Ota's secret counteroffer to throw the fight, deliberately loses the duel, and collects a generous payment from Ota. Zach's armour loses prestige but Henry profits from the arrangement."] = "Heinrich nimmt das geheime Gegenangebot von Meister Otto an, den Kampf absichtlich zu verlieren, verliert das Duell und kassiert von Otto eine großzügige Bezahlung. Zachs Rüstung verliert an Ansehen, aber Heinrich profitiert von der Abmachung."
  T["Instead of arranging a duel, Henry steals Ota's armour from his workshop and brings it to Zach, who rewards him for the theft. The duel never takes place."] = "Statt ein Duell auszutragen, stiehlt Heinrich die Rüstung von Meister Otto aus dessen Werkstatt und bringt sie zu Zach, der ihn für den Diebstahl belohnt. Das Duell findet nie statt."
  T["Henry kills the Bailiff, Ota, or Zach, making the quest impossible to complete. The quest is cancelled immediately upon the death of any of these key characters."] = "Heinrich tötet den Vogt, Meister Otto oder Zach, und die Quest lässt sich nicht mehr abschließen. Stirbt eine dieser Schlüsselfiguren, wird die Quest sofort abgebrochen."
  T["Henry and both Matus and Fricek successfully steal the money transport, share the loot at the hangman's tree, and the quest ends with everyone celebrating. Both companions survive and receive their cut."] = "Heinrich, Matthäus und Fritz überfallen erfolgreich den Geldtransport, teilen die Beute am Galgenbaum, und die Quest endet mit einer Feier. Beide Gefährten überleben und bekommen ihren Anteil."
  T["Henry completes the heist but one of the two companions (Matus or Fricek) dies during the operation. The survivor meets Henry at the hangman's tree to collect their share, and the quest ends."] = "Heinrich bringt den Raub zu Ende, aber einer der beiden Gefährten (Matthäus oder Fritz) stirbt dabei. Der Überlebende trifft Heinrich am Galgenbaum, um seinen Anteil abzuholen, und die Quest endet."
  T["Both Matus and Fricek die during or after the heist. Henry ends up with all the stolen money and the quest closes without sharing."] = "Matthäus und Fritz sterben beide während oder nach dem Raub. Heinrich behält das ganze gestohlene Geld, und die Quest endet, ohne dass geteilt wird."
  T["Henry refuses to pay Matus and Fricek their share at the hangman's tree (giveMoneyTimeOut expires or he provokes them), causing them to turn hostile. Henry keeps the entire sum and the quest ends."] = "Heinrich weigert sich, Matthäus und Fritz am Galgenbaum ihren Anteil auszuzahlen (giveMoneyTimeOut läuft ab oder er provoziert sie), und die beiden werden feindselig. Heinrich behält die ganze Summe, und die Quest endet."
  T["Henry takes the money bag from the chest himself (removeMoneyBagFromChest) without coordinating with Matus and Fricek, causing the quest to be canceled as a betrayal."] = "Heinrich nimmt den Geldsack eigenmächtig aus der Truhe (removeMoneyBagFromChest), ohne sich mit Matthäus und Fritz abzusprechen; die Quest wird als Verrat abgebrochen."
  T["Matus gets hold of the money bag (matusHasBagOfMoney completes), triggering a reputation penalty and immediate quest cancellation — the heist falls apart due to Matus's betrayal."] = "Matthäus bringt den Geldsack an sich (matusHasBagOfMoney ist erfüllt). Das kostet Ansehen und bricht die Quest sofort ab: Der Raub scheitert an Matthäus' Verrat."
  T["Henry declines to participate in the heist from the start. Matus and Fricek head to camp without him and the quest ends without the robbery taking place."] = "Heinrich lehnt es von Anfang an ab, beim Raub mitzumachen. Matthäus und Fritz ziehen ohne ihn ins Lager, und die Quest endet, ohne dass der Überfall stattfindet."
  T["Henry helps the charlatan successfully scare the village by completing the haunting tasks and the night scaring phase, then speaks with the charlatan the morning after. The quest ends with the village believing in the revenant and the charlatan paid."] = "Heinrich hilft dem Scharlatan, das Dorf in Angst zu versetzen: Er erledigt die Spukaufgaben und die nächtliche Schreckphase und spricht am nächsten Morgen mit dem Scharlatan. Die Quest endet damit, dass das Dorf an den Wiedergänger glaubt und der Scharlatan bezahlt wird."
  T["The charlatan is killed at any point during the quest, causing it to be cancelled. Henry failed to protect the key NPC."] = "Der Scharlatan wird zu irgendeinem Zeitpunkt der Quest getötet, und die Quest wird abgebrochen. Heinrich hat den wichtigsten NPC nicht beschützt."
  T["The gossip hag is killed before Henry has spoken to her about the brave guy, removing a required quest NPC and cancelling the quest."] = "Das Tratschweib wird getötet, bevor Heinrich mit ihm über den Furchtlosen gesprochen hat. Damit fehlt ein für die Quest nötiger NPC, und die Quest wird abgebrochen."
  T["Henry is spotted too many times at the bandit camp or accumulates too many trespass strikes, causing the brave guys to report him to the village and the quest to fail."] = "Heinrich wird zu oft am Banditenlager gesehen oder sammelt zu viele Verstöße wegen unbefugten Betretens; die Furchtlosen melden ihn dem Dorf, und die Quest scheitert."
  T["Henry successfully scares the bandits into leaving without killing them, completing the bandit sub-objective peacefully."] = "Heinrich jagt den Banditen solche Angst ein, dass sie abziehen, ohne dass er sie töten muss; die Unteraufgabe zu den Banditen ist friedlich erfüllt."
  T["All four bandits are killed instead of being scared away. Henry can blame the revenant for their deaths to gain extra fear factor."] = "Alle vier Banditen werden getötet, statt verscheucht zu werden. Heinrich kann ihren Tod dem Wiedergänger anlasten, um die Angst im Dorf zusätzlich zu schüren."
  T["Henry and the Talmberg soldiers kill all the bandits attacking the barbican. The battle ends in victory and the post-battle cutscene plays."] = "Heinrich und die Talmberger Waffenknechte töten alle Banditen, die den Vorhof angreifen. Die Schlacht endet siegreich, und die Zwischensequenz nach der Schlacht läuft."
  T["Henry opens the barbican gate (via interaction trigger) during the battle, ending the engagement without killing all enemies. The post-battle cutscene plays."] = "Heinrich öffnet während der Schlacht das Fallgatter zum Vorhof (über einen Interaktionsauslöser) und beendet das Gefecht, ohne alle Feinde zu töten. Die Zwischensequenz nach der Schlacht läuft."
  T["The battle timer runs out before the bandits are defeated or the gate is opened, forcing the quest to end on a failure path through the shared end objective."] = "Der Schlacht-Timer läuft ab, bevor die Banditen besiegt sind oder das Tor geöffnet ist; die Quest endet über die gemeinsame Aufgabe „end“ auf einem Fehlschlag-Pfad."
  T["Henry successfully completes all sub-tasks for the siege — securing meat, beer, potions, resin, a priest, and a healer — then reports to Borek after clearing the bandit camps, allowing the assault on Talmberg to proceed fully prepared."] = "Heinrich erledigt alle Teilaufträge für die Belagerung (Fleisch, Bier, Tränke, Pech, ein Priester und ein Heiler) und erstattet Herrn Robard Bericht, nachdem er die Banditenlager ausgehoben hat. So kann der Sturm auf Talmberg bestens vorbereitet beginnen."
  T["After the trebuchet is attacked and Henry speaks with Divis, the quest ends immediately and transitions to the assault phase without completing the bandit camp clearance, bypassing the full preparation loop."] = "Nachdem der Tribok angegriffen wurde und Heinrich mit Herrn Diwisch gesprochen hat, endet die Quest sofort und geht in die Angriffsphase über, ohne dass die Banditenlager ausgehoben sind; die vollständige Vorbereitung wird übersprungen."
  T["Henry fails to return the brewed potions to the camp in time, causing the potion sub-quest to expire and the soldiers to go without the alchemical boost."] = "Heinrich bringt die gebrauten Tränke nicht rechtzeitig ins Lager. Die Trank-Unterquest verfällt, und die Soldaten müssen ohne die alchemistische Stärkung auskommen."
  T["The field medic Nikodem is killed before Henry can complete the healer sub-quest, cancelling the getHealer objective and leaving the army without a surgeon."] = "Der Heiler Bruder Nicodemus wird getötet, bevor Heinrich die Heiler-Unterquest abschließen kann. Die Aufgabe getHealer wird abgebrochen, und das Heer steht ohne Wundarzt da."
  T["Henry kills the innkeeper Ondrej himself, collapsing the beer supply chain and cancelling both beer-tracking objectives, leaving the soldiers without ale."] = "Heinrich tötet den Wirt Andreas selbst. Die Bierversorgung bricht zusammen, beide Bier-Aufgaben werden abgebrochen, und die Soldaten bleiben ohne Bier."
  T["Fejfar, a key camp contact, dies during the preparation phase, registering as a negative event in the quest's parallel tracking and marking a failed sub-outcome."] = "Tobias Feyfar, ein wichtiger Ansprechpartner im Lager, stirbt während der Vorbereitungen. Das wird in der parallelen Verfolgung der Quest als negatives Ereignis erfasst und als gescheitertes Teilergebnis markiert."
  T["Henry brings food, then goes to speak with the father figure, completing the quest. This is a linear test quest with no branching choices or failure states."] = "Heinrich bringt Essen und spricht dann mit der Vaterfigur; damit ist die Quest abgeschlossen. Es ist eine lineare Testquest ohne Verzweigungen oder Fehlschläge."
  T["The quest completes normally. This is a simple open-world utility quest with no branching narrative choices or moral consequences."] = "Die Quest wird regulär abgeschlossen. Es ist eine einfache Hilfsquest in der offenen Welt ohne erzählerische Verzweigungen oder moralische Folgen."
  T["Theresa completes all chapters of her story — the village, nails, escape, finding her brother, and returning — then transfers to the next level. This is the sole narrative ending for this linear prologue quest."] = "Theresa durchläuft alle Kapitel ihrer Geschichte (das Dorf, die Nägel, die Flucht, die Suche nach ihrem Bruder und die Heimkehr) und wechselt dann auf die nächste Karte. Das ist das einzige erzählerische Ende dieser linearen Prologquest."
  T["Henry kills the wolf before it reaches Blanka, she collects herbs undisturbed, and the quest ends with Blanka successfully gathering what she came for. This is the best possible outcome."] = "Theresa tötet den Wolf, bevor er Bianca erreicht; Bianca sammelt ungestört Kräuter, und die Quest endet damit, dass sie alles findet, weswegen sie gekommen ist. Das ist der bestmögliche Ausgang."
  T["Henry was not guarding Blanka when the wolf appeared, kills or scares off the wolf, then has to find Blanka who fled. The quest still completes but Henry failed to protect her directly."] = "Theresa hat Bianca nicht bewacht, als der Wolf auftauchte; sie tötet oder verscheucht den Wolf und muss dann die geflohene Bianca suchen. Die Quest wird trotzdem abgeschlossen, aber Theresa hat Bianca nicht unmittelbar beschützt."
  T["Blanka already has belladonna at the start of the quest, so the herb-gathering excursion is skipped entirely and the quest ends immediately via the belladonaStarter shortcut."] = "Bianca hat zu Beginn der Quest schon Tollkirsche, also entfällt der Ausflug zum Kräutersammeln ganz, und die Quest endet sofort über die Abkürzung belladonaStarter."
  T["Blanka is knocked unconscious at any point during the quest. The engine detects her unconscious state via DeadUnconsciousGate, completes blankaUnconscious, and the quest is cancelled via cleanUp."] = "Bianca wird zu irgendeinem Zeitpunkt der Quest bewusstlos geschlagen. Die Engine erkennt ihre Bewusstlosigkeit über das DeadUnconsciousGate, erfüllt blankaUnconscious, und die Quest wird über cleanUp abgebrochen."
  T["The quest fails through a generic failure condition (e.g. Theresa abandons Blanka or another hard-fail trigger fires), cancelling the quest via cleanUp without any successful outcome."] = "Die Quest scheitert an einer allgemeinen Fehlschlagbedingung (z. B. lässt Theresa Bianca im Stich, oder ein anderer harter Fehlschlag-Auslöser greift); die Quest wird ohne jedes Erfolgsergebnis über cleanUp abgebrochen."
  T["Henry gathers all three required supplies (cloths/bandages, herbs, and water) and successfully treats Theresa's injured brother Frantisek. The brother survives and the quest ends with a cutscene of his recovery."] = "Theresa besorgt alle drei nötigen Dinge (Tücher/Verbände, Kräuter und Wasser) und versorgt ihren verletzten Bruder Franta. Der Bruder überlebt, und die Quest endet mit einer Zwischensequenz seiner Genesung."
  T["Frantisek dies before Henry can treat him — either Henry arrives too late or fails to act in time. Completing brotherIsDead triggers a Game Over with reason 'game_over_simek'."] = "Franta stirbt, bevor Theresa ihn versorgen kann, weil sie zu spät kommt oder nicht rechtzeitig handelt. Die Erfüllung von brotherIsDead löst ein Game Over mit dem Grund „game_over_simek“ aus."
  T["Henry and Theresa successfully escape the Cuman-occupied mill, reach the mines, and reunite with Simek and the others. The quest ends with the closing cutscene after Theresa stays outside the mine."] = "Heinrich und Theresa entkommen aus der von Kumanen besetzten Mühle, erreichen die Mine und finden dort Samuel und die anderen wieder. Die Quest endet mit der abschließenden Zwischensequenz, nachdem Theresa vor der Mine geblieben ist."
  T["Henry leaves the designated escape area or is caught by the Cumans, triggering an immediate game over screen. The quest fails without any narrative resolution."] = "Theresa verlässt den vorgesehenen Fluchtbereich oder wird von den Kumanen erwischt; sofort erscheint der Game-Over-Bildschirm. Die Quest scheitert ohne jede erzählerische Auflösung."
  T["Henry completes the Theresa relationship events, including the stablehand/apprentice argument dialogue and optional treasure map. The quest ends after the start objective resolves."] = "Heinrich durchläuft die Beziehungsereignisse mit Theresa, darunter das Streitgespräch zwischen Stallknecht und Lehrling und die optionale Schatzkarte. Die Quest endet, sobald die Aufgabe „start“ erledigt ist."
  T["Henry completes the level transition sequence: data is prepared and transferred, a healing buff is applied, and the game switches to the Rataje DLC4 level where Theresa triggers a forced dialogue to conclude the quest."] = "Heinrich durchläuft den Kartenwechsel: Die Daten werden vorbereitet und übertragen, ein Heilungsbonus wird angewendet, und das Spiel wechselt auf die Karte des Prologs von „Das Los einer Frau“, wo Theresa ein erzwungenes Gespräch auslöst, das die Quest beendet."
  T["Henry helps Johanka by ensuring Matthias invites her to the dance, either by bringing his lucky dice or getting Fritz to teach lockpicking, then reports back to Johanka with the result. The quest ends normally through the bringDice or makeSureMatejInvitesJohanka path."] = "Theresa hilft Johanka, indem sie dafür sorgt, dass Matthias Johanka zum Tanz einlädt: Sie bringt ihm seinen Glückswürfel oder bringt Fritz dazu, ihm das Schlossknacken beizubringen, und berichtet Johanka dann vom Ergebnis. Die Quest endet regulär über den Weg bringDice oder makeSureMatejInvitesJohanka."
  T["The quest window passes without Henry completing the task — the next-day timer fires, which cancels the end objective and causes the quest to be cancelled via CancelQuest. No meaningful outcome is achieved for Johanka."] = "Das Zeitfenster der Quest verstreicht, ohne dass der Auftrag erledigt wird: Der Timer für den nächsten Tag löst aus, bricht die Aufgabe „end“ ab, und die Quest wird über CancelQuest abgebrochen. Für Johanka wird nichts Nennenswertes erreicht."
  T["Johanka falls unconscious (or is knocked out) while the quest is active and the end objective is still pending. The DeadUnconsciousGate in the BT detects her unconscious state and cancels the end objective, triggering a CancelQuest."] = "Johanka verliert das Bewusstsein (oder wird bewusstlos geschlagen), während die Quest aktiv ist und die Aufgabe „end“ noch aussteht. Das DeadUnconsciousGate im Verhaltensbaum erkennt ihre Bewusstlosigkeit und bricht die Aufgabe „end“ ab; das löst ein CancelQuest aus."
  T["The Cumans attack Skalitz. Henry witnesses the attack and the quest ends as the main story takes over."] = "Die Kumanen überfallen Skalitz. Heinrich wird Zeuge des Überfalls, und die Quest endet, als die Hauptgeschichte übernimmt."
  T["The Cumans attack Skalitz via the alternate cutscene path (Henry not present at the nails scene). Quest ends identically."] = "Die Kumanen überfallen Skalitz über den alternativen Pfad der Zwischensequenz (Heinrich ist bei der Szene mit den Nägeln nicht dabei). Die Quest endet genauso."
  T["Henry completes the introductory monologue, optionally follows the dog to Drizek, and returns to Skalitz, ending the quest normally. This is the sole narrative path for this linear DLC intro quest."] = "Theresa bringt den einleitenden Monolog hinter sich, folgt auf Wunsch dem Hund zu Holba und kehrt nach Skalitz zurück; die Quest endet regulär. Das ist der einzige erzählerische Weg dieser linearen Einführungsquest des DLC."
  T["Henry finds the stolen silver and brings it to Father (the miller). The quest ends successfully with the silver returned."] = "Theresa findet das gestohlene Silber und bringt es Vater (dem Müller). Die Quest endet erfolgreich, das Silber ist zurück."
  T["Henry already has the stolen silver at quest start and hands it over immediately, skipping the search entirely."] = "Theresa hat das gestohlene Silber schon bei Questbeginn und übergibt es sofort; die Suche entfällt ganz."
  T["Theresa declines to help search for the silver. The quest is logged as declined and does not proceed to recovery."] = "Theresa lehnt es ab, bei der Suche nach dem Silber zu helfen. Die Quest wird als abgelehnt verbucht, und es kommt nicht zur Rückgabe."
  T["Theresa is caught while searching for the silver, resulting in a bad outcome for her and the quest."] = "Theresa wird bei der Suche nach dem Silber erwischt; das geht für sie und die Quest schlecht aus."
  T["Nemoj, the guard at the mine, is killed during the quest, triggering a failure state."] = "Vormann Wendel, der Wächter an der Mine, wird während der Quest getötet; das führt zum Fehlschlag."
  T["Theresa successfully helps all five survivors (Drizek, Sobehrd, Jarmila, Julian, and Maros) escape or recover. The quest ends normally via endQuest after all five xIsSaved objectives complete."] = "Theresa hilft allen fünf Überlebenden (Holba, Töpfer Stanislav, Jarmila, Holzfäller Julian und Marosch), zu entkommen oder sich zu erholen. Die Quest endet regulär über endQuest, nachdem alle fünf Aufgaben xIsSaved erfüllt sind."
  T["At least one survivor is saved but one or more die before Theresa can help them. The quest still ends via endQuest because survivorsSaved > 0 when all active survivors and markers are resolved."] = "Mindestens ein Überlebender wird gerettet, aber einer oder mehrere sterben, bevor Theresa ihnen helfen kann. Die Quest endet trotzdem über endQuest, weil survivorsSaved > 0 ist, sobald alle aktiven Überlebenden und Markierungen abgehandelt sind."
  T["Every survivor dies before Theresa saves anyone (survivorsSaved == 0). The engine calls CancelQuest instead of starting endQuest, ending the quest in failure."] = "Alle Überlebenden sterben, bevor Theresa jemanden rettet (survivorsSaved == 0). Die Engine ruft CancelQuest auf, statt endQuest zu starten, und die Quest scheitert."
  T["Theresa completes her morning chores, helps her father with his tasks, retrieves the dress from the chest, and the quest ends with the bittersweet celebration cutscene. This is the main narrative conclusion of the quest."] = "Theresa erledigt ihre morgendlichen Pflichten, hilft ihrem Vater bei seinen Arbeiten, holt das Kleid aus der Truhe, und die Quest endet mit der bittersüßen Zwischensequenz des Festes. Das ist der erzählerische Hauptabschluss der Quest."
  T["Henry collects all scattered pages and returns them to the librarian, who reassembles the book and rewards Henry with access to the forbidden books cabinet. The quest completes normally."] = "Heinrich sammelt alle verstreuten Seiten und bringt sie dem Bibliothekar, der das Buch wieder zusammenfügt und Heinrich mit Zugang zum Schrank mit den verbotenen Büchern belohnt. Die Quest wird regulär abgeschlossen."
  T["The librarian dies before the quest can be completed, causing the quest to be cancelled outright with no resolution."] = "Der Bibliothekar stirbt, bevor die Quest abgeschlossen werden kann; die Quest wird sofort ohne Auflösung abgebrochen."
  T["Henry enters the tournament and wins, then reports the victory to Ptacek. The quest ends with a successful outcome and the winner's reward."] = "Heinrich tritt im Turnier an, gewinnt und meldet Herrn Hans Capon den Sieg. Die Quest endet erfolgreich mit dem Siegerpreis."
  T["Henry enters the tournament but loses, then reports the result to Ptacek. The quest ends without the prize but without failure."] = "Heinrich tritt im Turnier an, verliert aber und meldet Herrn Hans Capon das Ergebnis. Die Quest endet ohne Preis, aber auch ohne Fehlschlag."
  T["Henry fails to attend the tournament twice, missing both opportunities. The quest ends with a cancelled journal note and no reward."] = "Heinrich erscheint zweimal nicht zum Turnier und verpasst beide Gelegenheiten. Die Quest endet mit einem Abbruchvermerk im Questlog und ohne Belohnung."
  T["The main story quest q_counterOffensive begins, automatically cancelling or deactivating this quest before it can be completed."] = "Die Hauptquest q_counterOffensive beginnt und bricht diese Quest automatisch ab oder deaktiviert sie, bevor sie abgeschlossen werden kann."
  T["Henry investigates Svatopluk's death, survives or avoids the ambush, informs the blacksmith about Black Peter's treachery, and completes the quest with Cerny Petr still alive. The smith learns the truth and Henry receives a reward."] = "Heinrich untersucht Svatopluks Tod, übersteht den Hinterhalt oder entgeht ihm, berichtet dem Schmied vom Verrat des Schwarzen Peter und schließt die Quest ab, während der Schwarze Peter noch lebt. Der Schmied erfährt die Wahrheit, und Heinrich erhält eine Belohnung."
  T["Henry enters the tournament, defeats Cerny Petr in combat, and the quest resolves with Black Peter beaten publicly. Henry then reports back to the smith."] = "Heinrich tritt im Turnier an und besiegt den Schwarzen Peter im Kampf; die Quest endet damit, dass der Schwarze Peter öffentlich geschlagen ist. Danach erstattet Heinrich dem Schmied Bericht."
  T["Cerny Petr ambushes Henry with a poisoned weapon; Henry survives, discovers the poison plot, and reports the ambush to the blacksmith via the smithClosure sub-quest."] = "Der Schwarze Peter lauert Heinrich mit einer vergifteten Waffe auf; Heinrich überlebt, deckt den Giftanschlag auf und meldet den Hinterhalt über die Unterquest smithClosure dem Schmied."
  T["Cerny Petr is killed during or outside the ambush encounter. The quest deactivates if it has not yet fully started, or continues to a reduced closure if it has, with Henry unable to bring Black Peter to proper justice."] = "Der Schwarze Peter wird beim Hinterhalt oder außerhalb davon getötet. Hat die Quest noch nicht richtig begonnen, wird sie deaktiviert; sonst läuft sie auf einen verkürzten Abschluss hinaus, und Heinrich kann den Schwarzen Peter nicht ordentlich zur Rechenschaft ziehen."
  T["The blacksmith is killed at any point while the quest is active, causing the quest to be immediately cancelled and a failure journal entry to be recorded."] = "Der Schmied wird zu irgendeinem Zeitpunkt getötet, während die Quest aktiv ist; die Quest wird sofort abgebrochen, und im Questlog wird ein Fehlschlag vermerkt."
  T["The quest's resolution is triggered by an external event before Henry formally receives it, skipping the investigation entirely and jumping straight to the end-quest-line closure."] = "Ein äußeres Ereignis löst den Abschluss der Quest aus, bevor Heinrich sie offiziell erhält; die Ermittlungen entfallen ganz, und es geht direkt zum Abschluss der Questreihe."
  T["Henry obtains a genuine tooth or bone relic of St. Procopius and returns it to Urban. Urban is satisfied and rewards Henry."] = "Heinrich beschafft eine echte Reliquie des heiligen Prokop, einen Zahn oder Knochen, und bringt sie Urban. Urban ist zufrieden und belohnt Heinrich."
  T["Henry obtains a fake bone from the charlatan and passes it off to Urban as a genuine relic. Urban's reputation suffers when the deception is discovered."] = "Heinrich besorgt sich beim Scharlatan einen falschen Knochen und dreht ihn Urban als echte Reliquie an. Als der Betrug auffliegt, leidet Urbans Ruf."
  T["Henry places the sacred bowl in the crypt as part of the quest resolution, completing the bone quest through the bowl path."] = "Heinrich stellt die heilige Schüssel als Teil der Auflösung in die Krypta und schließt die Reliquienquest so über den Weg mit der Schüssel ab."
  T["Urban dies during the quest, causing it to be cancelled outright with no resolution."] = "Urban stirbt während der Quest; die Quest wird sofort ohne Auflösung abgebrochen."
  T["Henry successfully accompanies Ptacek to the baths, wins the fist fight against Slavoj, and the bathmaster is punished. The quest ends with the final cutscene and Henry deciding Slavoj's fate."] = "Heinrich begleitet Herrn Hans Capon ins Badehaus, gewinnt den Faustkampf gegen Archibald, und der Bader wird bestraft. Die Quest endet mit der abschließenden Zwischensequenz, in der Heinrich über Archibalds Schicksal entscheidet."
  T["The quest is cancelled because Zdena or Klara died before the quest could proceed, making it impossible to complete the bathhouse visit."] = "Die Quest wird abgebrochen, weil Sidonia oder Klara gestorben ist, bevor es weitergehen konnte; der Besuch im Badehaus lässt sich nicht mehr abschließen."
  T["Henry failed to complete the quest before the in-game deadline, causing the quest to be cancelled via the timekeeper timeout."] = "Heinrich hat die Quest nicht vor Ablauf der Frist im Spiel abgeschlossen; die Quest wird über die Zeitüberschreitung des Zeitnehmers abgebrochen."
  T["Henry is caught trespassing while fetching wine and is thrown out of the town hall by the guard, failing to complete the errand."] = "Heinrich wird beim Weinholen beim unbefugten Betreten erwischt und von der Wache aus dem Rathaus geworfen; die Besorgung scheitert."
  T["Henry is arrested while attempting to obtain wine, ending up in jail and unable to complete the quest."] = "Heinrich wird beim Versuch, Wein zu beschaffen, verhaftet, landet im Kerker und kann die Quest nicht abschließen."
  T["Henry declines to get into the bath during the second dialog with Ptacek, taking an alternate path through the evening without bathing."] = "Heinrich lehnt im zweiten Gespräch mit Herrn Hans Capon ab, in den Zuber zu steigen, und verbringt den Abend auf einem anderen Weg, ohne zu baden."
  T["Henry helps the Waldensian Bauer family escape by convincing them to flee, then reports the outcome to Hanus. The heretics are saved and the vicar's mission is subverted."] = "Heinrich hilft der Waldenserfamilie von Hofbesitzer Bauer, indem er sie zur Flucht überredet, und berichtet Herrn Hanusch von Leipa dann vom Ausgang. Die Ketzer sind gerettet, und die Mission des Vikars ist vereitelt."
  T["The vicar dies (by Henry's hand or otherwise) after Henry has already accepted the quest, causing getRidOfVicar to complete and the quest to proceed to reporting to Hanus without saving the Bauers."] = "Der Vikar stirbt (durch Heinrichs Hand oder anders), nachdem Heinrich die Quest bereits angenommen hat. Damit ist getRidOfVicar erfüllt, und die Quest geht zum Bericht an Herrn Hanusch von Leipa über, ohne dass die Familie Bauer gerettet wird."
  T["Henry leaves the estate area before the supper cutscene completes and has not yet talked to the vicar about worship, or the timeout objective fires, causing the quest to be cancelled outright."] = "Heinrich verlässt das Gut, bevor die Zwischensequenz beim Abendessen vorbei ist, und hat noch nicht mit dem Vikar über den Gottesdienst gesprochen, oder die Zeitlimit-Aufgabe löst aus; die Quest wird sofort abgebrochen."
  T["Bauer and his wife are both killed before Henry can convince them to escape, causing the quest to be cancelled as there is no one left to save."] = "Hofbesitzer Bauer und seine Frau werden beide getötet, bevor Heinrich sie zur Flucht überreden kann. Die Quest wird abgebrochen, da niemand mehr zu retten ist."
  T["Henry helps Ales assign water-carrying and shit-carrying jobs to the applicants. All applicants are interviewed and jobs are finalized, completing the quest normally."] = "Heinrich hilft Alex, die Bewerber als Wasserträger und Scheißeträger einzuteilen. Alle Bewerber werden befragt und die Arbeiten verteilt; die Quest wird regulär abgeschlossen."
  T["Henry convinces Anezka to take the cook position at Hagen's house, giving her a better life. The quest ends with Anezka starting her new role as cook."] = "Heinrich überredet Agnes, die Stelle als Köchin im Haus von Konrad Hagen anzunehmen, und verhilft ihr so zu einem besseren Leben. Die Quest endet damit, dass Agnes ihre neue Stelle als Köchin antritt."
  T["The quest is forcibly cancelled because a critical NPC (Vanek, Hagen, or two applicants) died, making it impossible to complete the job assignment."] = "Die Quest wird zwangsweise abgebrochen, weil ein unverzichtbarer NPC (Kampfmeister Vanyek, Konrad Hagen oder zwei Bewerber) gestorben ist; die Arbeiten lassen sich nicht mehr verteilen."
  T["Ales, the overseer managing the job assignments, was killed before the process could be completed, derailing the entire quest."] = "Alex, der Aufseher, der die Arbeiten verteilt, wurde getötet, bevor alles erledigt war; damit ist die ganze Quest gescheitert."
  T["Henry successfully treats all three wounded patients (bandages Jan, fixes Tomas's broken leg, and obtains the diarrhoea potion for Filip), earning Sebastian's gratitude and a celebratory feast. The quest ends with the infirmary fully restored."] = "Heinrich versorgt alle drei Verwundeten (er verbindet Hannes aus Skalitz, richtet Thomas' gebrochenes Bein und beschafft für Phillip aus Skalitz den Trank gegen Durchfall) und erntet die Dankbarkeit von Sebastian vom Berg sowie ein Festmahl. Die Quest endet damit, dass die Krankenstube wieder ganz in Ordnung ist."
  T["Henry treats at least one but not all three patients before the quest resolves. The infirmary survives but not everyone was saved in time."] = "Heinrich versorgt mindestens einen, aber nicht alle drei Verwundeten, bevor die Quest endet. Die Krankenstube besteht weiter, aber nicht alle wurden rechtzeitig gerettet."
  T["All three patients die before Henry can treat them, either through neglect over too many in-game days or by Henry's hand. The quest ends in total failure with every wounded soul lost."] = "Alle drei Verwundeten sterben, bevor Heinrich sie versorgen kann, weil er sie zu viele Spieltage vernachlässigt oder sie selbst tötet. Die Quest endet mit einem völligen Fehlschlag: Kein Verwundeter hat überlebt."
  T["Johanka is killed during the quest, which immediately cancels the entire quest regardless of how many patients Henry has already helped."] = "Johanka wird während der Quest getötet; das bricht die gesamte Quest sofort ab, egal wie vielen Verwundeten Heinrich schon geholfen hat."
  T["Henry successfully helps set the trap for Zajic, delivers the document, and is rewarded by Sir Divis with a promotion and hunting rights. The quest ends with the endQuest objective after the final cutscene with Divis."] = "Heinrich hilft, Hanekin Hase die Falle zu stellen, überbringt das Dokument und wird von Herrn Diwisch mit einer Beförderung und Jagdrechten belohnt. Die Quest endet nach der abschließenden Zwischensequenz mit Herrn Diwisch über die Aufgabe endQuest."
  T["Zajic is killed during the quest, causing it to be cancelled. The trap cannot be sprung without Zajic alive."] = "Hanekin Hase wird während der Quest getötet, und die Quest wird abgebrochen. Ohne den lebenden Hanekin kann die Falle nicht zuschnappen."
  T["Marketa is killed during the quest, making it impossible to proceed with the kidnapping plan and causing the quest to be cancelled."] = "Margit wird während der Quest getötet; der Entführungsplan lässt sich nicht mehr umsetzen, und die Quest wird abgebrochen."
  T["Mikulas is killed during the quest, preventing him from signing the document and causing the quest to be cancelled."] = "Wildhüter Nickolas wird während der Quest getötet und kann das Dokument nicht mehr unterzeichnen; die Quest wird abgebrochen."
  T["Henry knocks out Marketa but drops her body before reaching Zajic's cave hideout, causing the quest to fail with reputation penalties."] = "Heinrich schlägt Margit bewusstlos, legt sie aber ab, bevor er Hanekin Hases Versteck in der Höhle erreicht; die Quest scheitert, und Heinrich verliert an Ansehen."
  T["Henry fails to complete the quest within the allotted time after Zajic honks his horn, causing the quest to be cancelled."] = "Heinrich schließt die Quest nicht innerhalb der vorgegebenen Zeit ab, nachdem Hanekin Hase in sein Horn geblasen hat; die Quest wird abgebrochen."
end)
-- Quest skips: the Quests tab's buttons, their tips and question (wording shared with KCD2 Companion), and
-- what completing an objective the way the game does reports (st_skip.lua, the endings' run)
fill(function(T)
  T["(risky)"] = "(riskant)"
  T["Skip anyway"] = "Trotzdem überspringen"
  T["Cancel"] = "Abbrechen"
  T["Don't remind me again"] = "Nicht mehr erinnern"
  T["Warn before a skip that can leave a quest stuck"] = "Vor einem Überspringen warnen, das eine Quest festfahren kann"
  T["what play does here could not be worked out"] = "was das Spiel hier sonst tut, ließ sich nicht ermitteln"
  T["Play does more here than the skip: "] = "Das Spiel tut hier mehr als das Überspringen: "
  T["Stopped at '%s': play does more there than a skip would. Skip it by hand if you want."] = "Angehalten bei „%s“: Das Spiel tut hier mehr, als ein Überspringen täte. Überspring es von Hand, wenn du willst."
  T["an item"] = "einen Gegenstand"
  T["a flag or counter"] = "einen Merker oder Zähler"
  T["a person or thing in the world"] = "eine Person oder Sache in der Welt"
  T["a cutscene or conversation"] = "eine Zwischensequenz oder ein Gespräch"
  T["another objective or quest"] = "eine andere Aufgabe oder Quest"
  T["a reward or other change"] = "eine Belohnung oder andere Änderung"
  T["A skip does only what the objective's own trigger does: anything else the quest does at that moment (an item handed over, a flag another quest reads) is missed and can leave the quest stuck. Keep a save from before it."] = "Überspringen tut nur, was der Auslöser der Aufgabe selbst tut: alles andere, was die Quest in dem Moment täte (ein übergebener Gegenstand, ein Merker, den eine andere Quest liest), fällt weg und kann die Quest festfahren. Behalte einen Spielstand von davor."
  T["Does what the game does here as well: "] = "Erledigt auch, was das Spiel hier tut: "
  T["Gives you the items it tracks; the game then completes it itself."] = "Gibt dir die Gegenstände, die sie verfolgt; das Spiel schließt sie dann selbst ab."
  T["Starts '%s'; the quest completes this from there."] = "Beginnt „%s“; die Quest schließt diese von dort aus ab."
  T["Completes '%s'; the quest completes this from there."] = "Schließt „%s“ ab; die Quest schließt diese von dort aus ab."
  T["Outcome [%s] (%s): %d step(s)"] = "Ende [%s] (%s): %d Schritt(e)"
  T["Ending run done: %d step(s)"] = "Ende durchgespielt: %d Schritt(e)"
  T["Replay step %s failed: %s"] = "Nachgespielter Schritt %s fehlgeschlagen: %s"
  T["Completed [%s] the way the game does; %d step(s) of it failed"] = "[%s] so abgeschlossen, wie das Spiel es tut; %d Schritt(e) davon fehlgeschlagen"
  T["Completed [%s] the way the game does"] = "[%s] so abgeschlossen, wie das Spiel es tut"
  T["The game completed [%s] from [%s]"] = "Das Spiel hat [%s] aus [%s] heraus abgeschlossen"
  T["The game completed [%s] from the items"] = "Das Spiel hat [%s] durch die Gegenstände abgeschlossen"
  T["The game did not complete [%s] from [%s]: completed it directly"] = "Das Spiel hat [%s] nicht aus [%s] heraus abgeschlossen: direkt abgeschlossen"
  T["The game did not complete [%s] from the items: completed it directly"] = "Das Spiel hat [%s] nicht durch die Gegenstände abgeschlossen: direkt abgeschlossen"
  T["Could not give item %s: %s"] = "Gegenstand %s konnte nicht gegeben werden: %s"
  T["Gave the %d item(s) [%s] tracks; the game completes it from them"] = "%d Gegenstand/Gegenstände, die [%s] verfolgt, gegeben; das Spiel schließt sie damit ab"
  T["Fired [%s], which the quest completes [%s] from"] = "[%s] ausgelöst, woraus die Quest [%s] abschließt"
  T["The game never completes [%s] itself: completed it anyway"] = "Das Spiel schließt [%s] nie selbst ab: trotzdem abgeschlossen"
  T["Completed [%s]; play does more here, which was not done"] = "[%s] abgeschlossen; das Spiel tut hier mehr, was nicht getan wurde"
  T["Completed [%s]"] = "[%s] abgeschlossen"
end)
